const a=e=>{var t;return e.sol.ok?-(((t=e.sol.memberMap.BR)==null?void 0:t.stations[0].M)??0):0},n=[{id:"l.rc-sys-frames.three",xp:30,title:{en:"Choose the straight three-hinged frame and check that its knee carries the whole wL²/8",ar:"اختار الإطار ثلاثي المفصلات المستقيم واتأكد إن ركنه شايل wL²/8 كله"},check:e=>e.template==="framefamily"&&e.params.sys==="3h"&&Number(e.params.f)===0&&e.sol.ok&&Math.abs(a(e)-Number(e.params.w)*Number(e.params.L)**2/8)<1},{id:"l.rc-sys-frames.order",xp:30,title:{en:"Without settlement, find the frame whose largest moment is the smallest",ar:"من غير هبوط، لاقي الإطار اللي أكبر عزم فيه هو الأصغر"},check:e=>e.template==="framefamily"&&e.params.sys==="fixed"&&Number(e.params.d)===0&&e.sol.ok},{id:"l.rc-sys-frames.settle",xp:40,title:{en:"Let the right footing of the fixed frame settle 30 mm and compare its two knees",ar:"خلّي القاعدة اليمين للإطار الثابت تهبط 30 مم وقارن ركنيه"},check:e=>e.template==="framefamily"&&e.params.sys==="fixed"&&Number(e.params.d)>=30&&e.sol.ok},{id:"l.rc-sys-frames.calm",xp:30,title:{en:"Settle the three-hinged frame by 30 mm: not one moment changes",ar:"نزّل الإطار ثلاثي المفصلات 30 مم: ولا عزم بيتغيّر"},check:e=>e.template==="framefamily"&&e.params.sys==="3h"&&Number(e.params.d)>=30&&e.sol.ok}],s=[{id:"l.rc-sys-frames.vw",xp:30,title:{en:"Two-hinged gable: read the thrust X from virtual work in the Hand method tab",ar:"جمالوني ذو مفصلين: اقرا الدفع X من الشغل الافتراضي في تبويب الحل اليدوي"},check:e=>e.template==="framefamily"&&e.params.sys==="2h"&&Number(e.params.f)>0&&e.tab==="hand"},{id:"l.rc-sys-frames.h3",xp:40,title:{en:"Fixed gable: compare the H/3 hinge with the exact frame",ar:"جمالوني ثابت: قارن مفصلة H/3 بالإطار المضبوط"},check:e=>e.template==="framefamily"&&e.params.sys==="fixed"&&Number(e.params.f)>0&&e.tab==="hand"},{id:"l.rc-sys-frames.steep",xp:30,title:{en:"Raise the rise of the three-hinged gable to 4 m and watch its knees ease",ar:"زوّد ارتفاع الجمالوني ثلاثي المفصلات لـ 4 م وشوف أركانه وهي بترتاح"},check:e=>e.template==="framefamily"&&e.params.sys==="3h"&&Number(e.params.f)>=4&&e.sol.ok}],i=[{id:"l.rc-sys-frames.table",xp:30,title:{en:"Open the distribution table of the two-bay frame",ar:"افتح جدول التوزيع بتاع الإطار ذو البايكتين"},check:e=>e.template==="multibay"&&e.tab==="hand"},{id:"l.rc-sys-frames.bays3",xp:40,title:{en:"Add a third bay: the inner joints no longer balance by symmetry",ar:"زوّد باكية تالتة: العقد الداخلية مابقتش تتوازن بالتماثل"},check:e=>e.template==="multibay"&&e.params.n==="3"&&e.tab==="hand"},{id:"l.rc-sys-frames.fixbase",xp:30,title:{en:"Fix the column bases and see the edge columns take a bigger share",ar:"ثبّت ركائز الأعمدة وشوف الأعمدة الطرفية بتاخد نصيب أكبر"},check:e=>e.template==="multibay"&&e.params.bases==="fixed"&&e.sol.ok}],o=[{id:"l.rc-sys-frames.beam",xp:30,title:{en:"Find a section of the frame where P may be neglected (designed as a beam)",ar:"لاقي قطاع في الإطار ينفع نهمل فيه P (بيتصمم ككمرة)"},check:e=>e.mode==="studio"&&e.methods.includes("beam")},{id:"l.rc-sys-frames.es",xp:40,title:{en:"Find a section designed by the e_s method (large eccentricity)",ar:"لاقي قطاع بيتصمم بطريقة e_s (لامركزية كبيرة)"},check:e=>e.mode==="studio"&&e.methods.includes("es")}],r={base:"hinged",L:16,H:6,w:70,P:0,Lc:0,wc:0,Pc:0,Hload:0,b:350,tg:1300,tc:1e3,spacing:7},m={sections:[{id:"family",title:{en:"The frame family",ar:"عيلة الإطارات"},blocks:[{t:"p",text:{en:"A frame is a beam cast together with its columns, so the columns share its bending. The family has three members: the **three-hinged frame** — hinges at both footings and at the crown, statically determinate; the **two-hinged frame** — hinges at the footings only, indeterminate to the first degree; and the **fixed frame** — fixed bases, three redundants (two once symmetry is used). Each comes straight or **inclined (gable)**. The rule of the family: **the more redundants, the smaller the moments** — lighter members, longer spans, a cheaper frame — **and the more a settling footing hurts it**.",ar:"الإطار كمرة مصبوبة مع أعمدتها، فالأعمدة بتشاركها في الانحناء. العيلة فيها تلات أفراد: **الإطار ثلاثي المفصلات** — مفصلات عند القاعدتين وعند التاج، محدد استاتيكياً؛ و**الإطار ذو المفصلين** — مفصلات عند القواعد بس، غير محدد من الدرجة الأولى؛ و**الإطار الثابت** — ركائز ثابتة، تلات مجاهيل زيادة (اتنين بعد ما نستغل التماثل). وكل واحد فيهم بييجي مستقيم أو **مائل (جمالوني)**. وقاعدة العيلة: **كل ما المجاهيل الزيادة تكتر العزوم بتصغر** — أعضاء أخف وبحور أطول وإطار أرخص — **وكل ما القاعدة اللي بتهبط تضره أكتر**."}},{t:"table",head:[{en:"Frame",ar:"الإطار"},{en:"Redundants",ar:"المجاهيل الزيادة"},{en:"Largest moment",ar:"أكبر عزم"},{en:"A settling footing",ar:"قاعدة بتهبط"}],rows:[[{en:"three-hinged",ar:"ثلاثي المفصلات"},"0",{en:"at the knees (wL²/8 when straight)",ar:"عند الأركان (wL²/8 لو مستقيم)"},{en:"no effect",ar:"مالهاش تأثير"}],[{en:"two-hinged",ar:"ذو مفصلين"},"1",{en:"usually at mid-span",ar:"غالباً في نص البحر"},{en:"one sinking footing: none; spreading footings: yes",ar:"قاعدة واحدة بتهبط: مفيش؛ قواعد بتبعد: أيوه"}],[{en:"fixed",ar:"ثابت الركائز"},"3 (2)",{en:"at the knees, and a moment into each footing",ar:"عند الأركان، وعزم داخل كل قاعدة"},{en:"bends the whole frame",ar:"بتحني الإطار كله"}]]},{t:"p",text:{en:"**Why the soil rules.** The bars of a frame are placed by its gravity moment diagram — tension on the outside at the knees, at the bottom in the span. Let one footing of a **three-hinged** frame settle: its two halves only tilt about the hinges, not one moment changes, and every bar stays on its tension face. Let one column of a **fixed** frame settle: the settlement adds moments that, at some sections, **reverse the sign** of the gravity moments — the diagram turns lopsided, and on one side a knee or a part of the span bends the other way. The bars there now lie on the compression face, the new tension face has almost none, and the frame may collapse. That is why weak soil gets the determinate frame **even when it costs more**.",ar:"**ليه التربة هي اللي بتحكم.** حديد الإطار بيتحط على حسب منحنى العزوم من الأحمال الرأسية — الشد بره عند الأركان، وتحت في البحر. لو قاعدة في إطار **ثلاثي المفصلات** هبطت: نصّيه بيميلوا حوالين المفصلات وبس، ولا عزم بيتغيّر، وكل سيخ بيفضل على وش الشد بتاعه. ولو عمود في إطار **ثابت الركائز** هبط: الهبوط بيضيف عزوم بتعكس **إشارة** عزوم الأحمال الرأسية في بعض القطاعات — المنحنى بيميل لناحية، وفي ناحية منهم ركن أو جزء من البحر بينحني في الاتجاه التاني. الحديد هناك بقى على وش الضغط، ووش الشد الجديد تقريباً مفيهوش حديد، والإطار ممكن ينهار. علشان كده التربة الضعيفة بتاخد الإطار المحدد **حتى لو تكلفته أعلى**."}},{t:"p",text:{en:"In the lab the three frames cover the same 18 m on 7 m columns under 60 kN/m, each sized by its own depth rule. The **three-hinged** frame hangs the whole simple-beam moment on its knees: 2430 kN·m at each knee, nothing at the crown. The **two-hinged** frame: 985.2 kN·m at the knees and 1444.8 at mid-span. The **fixed** frame: 1253.0 at the knees, 1177.0 at mid-span — and 612.3 kN·m into each footing. Now let the right footing settle 30 mm: the first two do not notice, while the knees of the fixed frame become 1428.1 and 1078.0 kN·m.",ar:"في المعمل التلات إطارات بيغطوا نفس الـ 18 م على أعمدة 7 م تحت 60 kN/m، وكل واحد متصمم بقاعدة العمق بتاعته. الإطار **ثلاثي المفصلات** بيعلّق عزم الكمرة البسيطة كله على أركانه: 2430 kN·m عند كل ركن، ومفيش حاجة عند التاج. والإطار **ذو المفصلين**: 985.2 kN·m عند الأركان و 1444.8 في نص البحر. والإطار **الثابت**: 1253.0 عند الأركان و 1177.0 في نص البحر — و 612.3 kN·m داخلين كل قاعدة. دلوقتي خلّي القاعدة اليمين تهبط 30 مم: أول اتنين مش هياخدوا بالهم، وأركان الإطار الثابت بتبقى 1428.1 و 1078.0 kN·m."}},{t:"lab",lab:"frame",height:480,props:{template:"framefamily",lockTemplate:!0,missions:n},caption:{en:"One span, three frames: switch the system, the rise and the settlement Δ of the right footing. The Hand method tab sizes the frame by its rule and solves it the short way.",ar:"بحر واحد وتلات إطارات: بدّل النظام وارتفاع الجمالون وهبوط القاعدة اليمين Δ. وتبويب الحل اليدوي بيحدد أبعاد الإطار بقاعدته وبيحله بالطريقة القصيرة."}},{t:"quiz",q:{kind:"mcq",q:{en:"A straight three-hinged frame carries a uniform load. Its knee moment is…",ar:"إطار ثلاثي المفصلات مستقيم شايل حمل موزع منتظم. عزم ركنه…"},options:[{en:"wL²/8 — the whole simple-beam moment",ar:"wL²/8 — عزم الكمرة البسيطة كله"},{en:"wL²/12",ar:"wL²/12"},{en:"zero — the hinges release it",ar:"صفر — المفصلات بتلغيه"}],answer:0,explain:{en:"The crown hinge has no moment, so the moment line of the beam is the simple-beam parabola shifted down by wL²/8: all of it appears at the knees.",ar:"مفصلة التاج مفيهاش عزم، فخط عزوم الكمرة هو قطع الكمرة البسيطة نازل بـ wL²/8: وده كله بيظهر عند الأركان."}}}]},{id:"choose",title:{en:"Span and soil decide",ar:"البحر والتربة هما اللي بيقرروا"},blocks:[{t:"table",head:[{en:"Frame",ar:"الإطار"},{en:"Usual span",ar:"البحر المعتاد"},{en:"Soil",ar:"التربة"}],rows:[[{en:"three-hinged",ar:"ثلاثي المفصلات"},{en:"12–16 m (on medium soil, and on weak soil too)",ar:"12–16 م (على التربة المتوسطة، وعلى التربة الضعيفة كمان)"},{en:"weak clay, 12–16 m; beyond 16 m a tied polygon frame, up to 24 m",ar:"طين ضعيف، 12–16 م؛ وبعد 16 م إطار مضلع بشداد، لحد 24 م"}],[{en:"two-hinged",ar:"ذو مفصلين"},"12–22 m",{en:"no soil data, intermediate soil or sand: 12–22 m",ar:"مفيش بيانات تربة، أو تربة متوسطة أو رمل: 12–22 م"}],[{en:"fixed",ar:"ثابت الركائز"},"12–24 m",{en:"hard soil — rock or dense (condensed) sand — 12–24 m; no data or sand 22–24 m",ar:"تربة قوية — صخر أو رمل متماسك (Condensed sand) — 12–24 م؛ ومفيش بيانات أو رمل 22–24 م"}]],caption:{en:"Gable (inclined) frames follow the same ranges as straight ones; a two-hinged frame with a sky-light is kept to 12–20 m. Below 12 m a girder usually does the job; beyond 24 m come polygon frames, arch girders and trusses.",ar:"الإطارات الجمالونية (المائلة) ليها نفس مدى المستقيمة؛ والإطار ذو المفصلين اللي فيه شخشيخة بيتحدد بـ 12–20 م. تحت 12 م الكمرة (Girder) غالباً بتكفي؛ وبعد 24 م بتيجي الإطارات المضلعة والكمرات المقوّسة والجمالونات."}},{t:"p",text:{en:"The soil decides how much redundancy the frame may have: weak clay settles unevenly, so it gets the determinate three-hinged frame up to 16 m, and beyond that a tied polygon frame on a hinge and a roller — its supports are determinate, so a settling footing only tilts it — up to 24 m; a hard soil — rock, or sand dense enough to count as hard — keeps its footings in place, so the stiffest frame — fixed — gives the smallest members. With no soil report the two-hinged frame is the safe middle, and the fixed frame takes over only for the last 22–24 m. The shape of the frame then picks the method: a symmetric straight frame under a symmetric load is solved by **one balance at the knee**; a gable, a frame with a link member or one that sways by **virtual work**; any frame is checked quickly by the **approximate hinges** at L/5 or H/3.",ar:"التربة هي اللي بتقرر الإطار ياخد قد إيه مجاهيل زيادة: الطين الضعيف بيهبط هبوط مش منتظم، فبياخد الإطار المحدد ثلاثي المفصلات لحد 16 م، وبعد كده إطار مضلع بشداد على مفصلة وركيزة متحركة — ركائزه محددة، فالقاعدة اللي بتهبط بتميّله بس — لحد 24 م؛ والتربة القوية — صخر، أو رمل متماسك كفاية إنه يتحسب تربة قوية — بتمسك القواعد مكانها، فالإطار الأجسأ — الثابت — بيدّي أصغر أعضاء. ولو مفيش تقرير تربة الإطار ذو المفصلين هو الوسط الآمن، والثابت بياخد الـ 22–24 م الأخيرة بس. وشكل الإطار بعد كده بيختار الطريقة: إطار مستقيم متماثل تحت حمل متماثل بيتحل بـ**توازن واحد عند الركن**؛ والجمالوني أو اللي فيه وصلة أو اللي بيتحرك جنب بـ**الشغل الافتراضي**؛ وأي إطار بيتراجع بسرعة بـ**المفصلات التقريبية** عند L/5 أو H/3."}},{t:"p",text:{en:"Every hall-frame problem then runs through the same seven steps:",ar:"وكل مسألة إطار صالة بعد كده بتمشي في نفس السبع خطوات:"}},{t:"steps",items:[{en:"**Choose the system** from the span and the soil (the table above).",ar:"**اختار النظام** من البحر والتربة (الجدول اللي فوق)."},{en:"**Draw the elevation and the plan** with the concrete dimensions of every member.",ar:"**ارسم الواجهة والمسقط** بالأبعاد الخرسانية لكل عنصر."},{en:"**Draw the slab reinforcement** on the same plan (the slabs themselves are designed as in the slab episodes: the thickness $t_s$ comes from the code table; $L_s/30$ for a one-way solid slab and $L_s/40$ for a two-way one are only the absolute minimums, never the design value; a two-way slab shares its load with the load-share coefficients).",ar:"**ارسم تسليح البلاطة** على نفس المسقط (البلاطات نفسها بتتصمم زي حلقات البلاطات: التخانة $t_s$ بتيجي من جدول الكود؛ و $L_s/30$ للبلاطة المصمتة في اتجاه واحد و $L_s/40$ للي في اتجاهين دول الحد الأدنى المطلق بس، مش قيمة التصميم؛ والبلاطة اللي في اتجاهين بتوزّع حملها بمعاملات التوزيع)."},{en:"**Distribute the slab loads** to the beams and find the loads that reach the frame.",ar:"**وزّع أحمال البلاطة** على الكمرات وطلّع الأحمال اللي بتوصل للإطار."},{en:"**Solve the frame**: its B.M.D. and N.F.D. (and the S.F.D. where the shear is checked).",ar:"**حل الإطار**: منحنى العزوم ومنحنى القوى العمودية (ومنحنى قوى القص لو هتراجع القص)."},{en:"**Design the critical sections** for M and N.",ar:"**صمّم القطاعات الحرجة** على M و N."},{en:"**Draw the reinforcement** of the frame in elevation, with its cross-sections.",ar:"**ارسم تسليح الإطار** في الواجهة، ومعاه القطاعات العرضية."}]},{t:"quiz",q:{kind:"mcq",q:{en:"A 23 m hall on sand, no further soil report. Which frame?",ar:"صالة 23 م على رمل، ومفيش تقرير تربة تاني. أنهي إطار؟"},options:[{en:"fixed",ar:"ثابت الركائز"},{en:"two-hinged",ar:"ذو مفصلين"},{en:"three-hinged",ar:"ثلاثي المفصلات"}],answer:0,explain:{en:"On sand the two-hinged frame goes to 22 m; 22–24 m calls for the fixed frame.",ar:"على الرمل الإطار ذو المفصلين بيوصل لـ 22 م؛ و 22–24 م عايزة الإطار الثابت."}}}]},{id:"dims",title:{en:"Concrete dimensions",ar:"الأبعاد الخرسانية"},blocks:[{t:"eq",tex:["t_{3h} = \\dfrac{L}{10},\\qquad t_{2h} = \\dfrac{L}{12} \\to \\dfrac{L}{14},\\qquad t_{fixed} = \\dfrac{L}{14} \\to \\dfrac{L}{16}","L' = 2\\sqrt{\\left(\\tfrac{L}{2}\\right)^2 + f^2},\\qquad b = \\max\\left(0.30,\\ \\dfrac{S}{20}\\right)"],caption:{en:"A gable frame of rise f uses its sloping length L′ instead of L. S = spacing of the frames.",ar:"الإطار الجمالوني اللي ارتفاعه f بياخد طوله المائل L′ بدل L. و S = المسافة بين الإطارات."}},{t:"p",text:{en:"The column is as deep as the beam at the knee, $t$. Under a hinge it tapers to $t/2$; its stiffness is that of a prism $\\tfrac56 t$ deep — the depth the taper has at $2h/3$ above the hinge — so $I_c = b(\\tfrac56 t)^3/12$ (the indeterminate-systems episode); a beam of the same $b$ and $t$, taken as a rectangle, then has $I_b = b\\,t^3/12 = (6/5)^3 I_c = 1.728\\,I_c$. A **three-hinged** frame tapers its beam as well: from $t$ at the knee to $t/2$ at the crown, its top face kept level. A **fixed** column is not tapered: it keeps one depth, $1.0$–$1.2\\,t$, from the knee all the way down to the footing, because its foot carries the base moment ($I_c = b\\,t_c^3/12$). **Examples.** A two-hinged frame of 17 m, frames 7 m apart: $t = 17/12 \\to 17/14 = 1.42 \\to 1.21$ m, take 1.30 m; $b = \\max(0.30,\\ 0.35) = 0.35$ m; the column 350 × 1300 at the knee tapers to 350 × 650 at the hinge. A fixed frame of 22 m: $22/14 \\to 22/16 = 1.57 \\to 1.38$ m, take 1.45 m; its column is 1.45–1.74 m deep over its whole height. A three-hinged gable of 14 m with a 2.5 m rise: $L' = 2\\sqrt{7^2 + 2.5^2} = 14.87$ m → $t = 1.49$ → 1.50 m, tapering to 0.75 m at the crown and at the hinges.",ar:"العمود عمقه زي الكمرة عند الركن، $t$. وتحت المفصلة بيتدرّج لـ $t/2$؛ وجساءته هي جساءة منشور عمقه $\\tfrac56 t$ — وده العمق اللي التدرّج بيوصله على ارتفاع $2h/3$ فوق المفصلة — يعني $I_c = b(\\tfrac56 t)^3/12$ (حلقة حل الأنظمة غير المحددة)؛ وكمرة بنفس $b$ و $t$، لو اتحسبت مستطيل، يبقى $I_b = b\\,t^3/12 = (6/5)^3 I_c = 1.728\\,I_c$. والإطار **ثلاثي المفصلات** بيدرّج كمرته كمان: من $t$ عند الركن لـ $t/2$ عند التاج، ووشها العلوي بيفضل أفقي. أما العمود **الثابت** فمش متدرّج: بياخد عمق واحد، $1.0$–$1.2\\,t$، من الركن لحد القاعدة، لأن رجله شايلة عزم القاعدة ($I_c = b\\,t_c^3/12$). **أمثلة.** إطار ذو مفصلين 17 م، والإطارات كل 7 م: $t = 17/12 \\to 17/14 = 1.42 \\to 1.21$ م، خد 1.30 م؛ و $b = \\max(0.30,\\ 0.35) = 0.35$ م؛ والعمود 350 × 1300 عند الركن بيتدرّج لـ 350 × 650 عند المفصلة. إطار ثابت 22 م: $22/14 \\to 22/16 = 1.57 \\to 1.38$ م، خد 1.45 م؛ وعموده عمقه 1.45–1.74 م على طوله كله. وجمالوني ثلاثي المفصلات 14 م بارتفاع 2.5 م: $L' = 2\\sqrt{7^2 + 2.5^2} = 14.87$ م ← $t = 1.49$ ← 1.50 م، بيتدرّج لـ 0.75 م عند التاج وعند المفصلات."}},{t:"p",text:{en:"**Axes and the height H.** The statical system is drawn on the member axes. A prismatic beam has its axis at mid-depth, $t/2$. A tapered column has a straight axis $t/4$ from its outer face: at the hinge the section is $t/4 + t/4$, at the knee $t/4$ outside the axis and $3t/4$ inside. The height of the analysis, $H$, runs from the hinge (or the top of a fixed footing) up to the beam axis. **Example.** Roof slab at +7.00, the hinge 1.20 m below the ground, a 1.30 m beam: $H = 7.00 + 1.20 - 0.65 = 7.55$ m; the column axis runs 0.325 m inside the outer face, so at the knee 0.975 m of the column lies inside it.",ar:"**المحاور والارتفاع H.** النظام الإنشائي بيترسم على محاور العناصر. الكمرة المنشورية محورها في نص عمقها، $t/2$. والعمود المتدرّج محوره خط مستقيم على بعد $t/4$ من وشه الخارجي: عند المفصلة القطاع $t/4 + t/4$، وعند الركن $t/4$ بره المحور و $3t/4$ جوه. وارتفاع التحليل $H$ من المفصلة (أو من وش القاعدة الثابتة) لحد محور الكمرة. **مثال.** بلاطة السقف عند +7.00، والمفصلة 1.20 م تحت الأرض، وكمرة 1.30 م: $H = 7.00 + 1.20 - 0.65 = 7.55$ م؛ ومحور العمود ماشي على بعد 0.325 م جوه الوش الخارجي، فعند الركن 0.975 م من العمود بتبقى جوه المحور."}},{t:"p",text:{en:"**The elevation.** The hinge (or the top of a fixed footing) sits about 1.0 m below the ground. Under the roof edge runs a window strip; below it the brick wall is held between **wall beams 250 × 500** — one under the windows, one near the ground — and the wall stands on a ground beam (semelle). No brick panel between beams and columns may exceed **30 m²**: with frames 6.5 m apart a panel is at most $30/6.5 = 4.62$ m high, so a taller wall needs one more wall beam.",ar:"**الواجهة.** المفصلة (أو وش القاعدة الثابتة) بتبقى حوالي 1.0 م تحت الأرض. وتحت حافة السقف بيمشي شريط شبابيك؛ وتحته حائط الطوب ماسكينه **كمرات حوائط 250 × 500** — واحدة تحت الشبابيك وواحدة قريب من الأرض — والحائط واقف على سملة. ومفيش باكية حائط بين الكمرات والأعمدة مساحتها تزيد عن **30 م²**: لو الإطارات كل 6.5 م يبقى أقصى ارتفاع للباكية $30/6.5 = 4.62$ م، والحائط الأعلى من كده محتاج كمرة حائط زيادة."}},{t:"p",text:{en:"**The drawing sheet.** One sheet per hall: the ELEVATION of a frame, the PLAN of the roof (and a second plan for a raised lantern roof), a SIDE VIEW, and a KEY PLAN at 1:200–1:400 with the drawn part hatched. Frames stand every $S$, secondary beams every 2–5 m, and the end (gable) wall gets columns every 4–8 m. An expansion joint is **two complete frames 2 cm apart**, shown on the plan and on the side view; in a three-hinged hall the crown gap also runs as a double line along the whole plan. On a gable roof the main slab bars are drawn folded down into the plan and bent over the ridge. **Example.** A 72 m hall in two parts of 36 m, frames every 6 m: each part has $36/6 + 1 = 7$ frames, 14 in all, two of them side by side at the joint.",ar:"**لوحة الرسم.** لوحة واحدة لكل صالة: الواجهة (ELEVATION) لإطار، ومسقط السقف (PLAN) (ومسقط تاني لسقف الشخشيخة المرفوع لو موجود)، ومنظر جانبي (SIDE VIEW)، ومسقط مفتاحي (KEY PLAN) بمقياس 1:200–1:400 والجزء المرسوم متهشّر. الإطارات كل $S$، والكمرات المتشالة كل 2–5 م، وحائط الواجهة الطرفية بياخد أعمدة جمالون كل 4–8 م. وفاصل التمدد عبارة عن **إطارين كاملين بينهم 2 سم**، بيظهروا في المسقط وفي المنظر الجانبي؛ وفي الصالة ثلاثية المفصلات فاصل التاج كمان بيظهر خط مزدوج على طول المسقط كله. وفي السقف الجمالوني حديد البلاطة الرئيسي بيترسم مفرود في المسقط ومكسّح فوق خط القمة. **مثال.** صالة 72 م متقسمة جزئين كل واحد 36 م، والإطارات كل 6 م: كل جزء فيه $36/6 + 1 = 7$ إطارات، 14 في المجموع، منهم اتنين جنب بعض عند الفاصل."}},{t:"quiz",q:{kind:"num",q:{en:"A two-hinged gable frame: span 16 m, rise 3 m. Its sloping length L′ (m)?",ar:"إطار جمالوني ذو مفصلين: البحر 16 م والارتفاع 3 م. طوله المائل L′ (م)؟"},answer:17.088,tol:.003,unit:"m",explain:{en:"$2\\sqrt{8^2 + 3^2} = 2\\sqrt{73} = 17.09$ m → $t = L'/12 \\to L'/14 = 1.42 \\to 1.22$ m.",ar:"$2\\sqrt{8^2 + 3^2} = 2\\sqrt{73} = 17.09$ م ← $t = L'/12 \\to L'/14 = 1.42 \\to 1.22$ م."}}}]},{id:"three",title:{en:"The three-hinged frame and its crown hinge",ar:"الإطار ثلاثي المفصلات ومفصلة التاج"},blocks:[{t:"p",text:{en:"Four reactions, four equations: the three of statics and the moment of one half about the crown hinge, which must be zero. Under a uniform load on plan, with columns $h$ and a rise $f$ ($f = 0$ for a straight beam):",ar:"أربع ردود أفعال وأربع معادلات: التلاتة بتوع الاتزان، وعزم نص واحد حوالين مفصلة التاج اللي لازم يبقى صفر. تحت حمل موزع منتظم على المسقط، وأعمدة $h$ وارتفاع $f$ ($f = 0$ للكمرة المستقيمة):"}},{t:"eq",tex:["X = \\dfrac{wL^2}{8\\,(h + f)},\\qquad Y = \\dfrac{wL}{2},\\qquad M_{knee} = X\\,h"],caption:{en:"For a straight frame M_knee = wL²/8: the whole simple-beam moment sits on the knees.",ar:"للإطار المستقيم M_knee = wL²/8: عزم الكمرة البسيطة كله قاعد على الأركان."}},{t:"p",text:{en:"**Example.** A straight frame of 14 m on 5.5 m columns under 40 kN/m: $X = 40\\times14^2/(8\\times5.5) = 178.2$ kN, $Y = 280$ kN, $M_{knee} = 178.2\\times5.5 = 980$ kN·m $= wL^2/8$. Give it a 2.5 m rise: $X = 980/8 = 122.5$ kN, the knee drops to 673.8 kN·m and the rafter sags only 23.9 kN·m, 5.91 m from the knee — the gable follows the load. That is why three-hinged frames are deep ($L/10$) and short (12–16 m).",ar:"**مثال.** إطار مستقيم 14 م على أعمدة 5.5 م تحت 40 kN/m: $X = 40\\times14^2/(8\\times5.5) = 178.2$ kN، و $Y = 280$ kN، و $M_{knee} = 178.2\\times5.5 = 980$ kN·m $= wL^2/8$. ادّيله ارتفاع 2.5 م: $X = 980/8 = 122.5$ kN، والركن بينزل لـ 673.8 kN·m والكمرة المائلة عزمها الموجب 23.9 kN·m بس، على بعد 5.91 م من الركن — الجمالون بيمشي مع الحمل. علشان كده الإطارات ثلاثية المفصلات عميقة ($L/10$) وقصيرة (12–16 م)."}},{t:"p",text:{en:"The **crown hinge** is a real hinge. Each half ends $X = t/2$ deep; two notches, top and bottom, leave a **neck** $X/3$ deep at mid-height, and the 2 cm gap that lets the halves turn runs through the notches. The main top and bottom bars of each half are closed into a **U** at the joint face; separate hinge bars cross through the neck as an X, with straight legs into both halves; and the stirrups are concentrated, **10Ø10 per metre over 1.0 m (or $t$)** on each side. For $t = 1.40$ m: ends 0.70 m deep and a 0.23 m neck. The footings of three- and two-hinged frames get real hinges too: the foot, $t/2$ deep, bears on a neoprene (or lead) plate $X/3$ wide, with dowels through it to stop the horizontal movement, as in the real-supports episode.",ar:"**مفصلة التاج** مفصلة حقيقية. كل نص بينتهي بعمق $X = t/2$؛ ونقرتين، فوق وتحت، بيسيبوا **رقبة** عمقها $X/3$ في النص، والفاصل 2 سم اللي بيسيب النصين يلفوا بيعدّي جوه النقرتين. الحديد الرئيسي العلوي والسفلي لكل نص بيتقفل على شكل **U** عند وش الوصلة؛ وأسياخ مفصلة منفصلة بتعدّي متقاطعة (X) جوه الرقبة، برجول مستقيمة في النصين؛ والكانات بتتركّز، **10Ø10 في المتر على طول 1.0 م (أو $t$)** من كل ناحية. لـ $t = 1.40$ م: أطراف عمقها 0.70 م ورقبة 0.23 م. وقواعد الإطارات ثلاثية وذات المفصلين بتاخد مفصلات حقيقية هي كمان: رجل العمود، وعمقها $t/2$، بترتكز على لوح نيوبرين (أو رصاص) عرضه $X/3$، وأشاير بتعدّي فيه علشان تمنع الحركة الأفقية، زي حلقة الركائز الحقيقية."}},{t:"eq",tex:["X = \\dfrac{t}{2},\\qquad a_{neck} = \\dfrac{X}{3},\\qquad g = 20\\ \\text{mm}"],caption:{en:"X = depth of each half at the hinge; a_neck = depth of the neck between the notches (and the width of the plate under a base hinge); g = the gap between the halves.",ar:"X = عمق كل نص عند المفصلة؛ و a_neck = عمق الرقبة بين النقرتين (وعرض اللوح تحت مفصلة القاعدة)؛ و g = الفاصل بين النصين."}},{t:"quiz",q:{kind:"num",q:{en:"A straight three-hinged frame: L = 12 m, h = 5 m, w = 50 kN/m. Thrust X (kN)?",ar:"إطار ثلاثي المفصلات مستقيم: L = 12 م، و h = 5 م، و w = 50 kN/m. الدفع الأفقي X (kN)؟"},answer:180,tol:.003,unit:"kN",explain:{en:"$50\\times144/(8\\times5) = 180$ kN; the knee takes $180\\times5 = 900$ kN·m $= wL^2/8$.",ar:"$50\\times144/(8\\times5) = 180$ kN؛ والركن بياخد $180\\times5 = 900$ kN·m $= wL^2/8$."}}}]},{id:"analysis",title:{en:"Two-hinged and fixed frames: which method",ar:"الإطارات ذات المفصلين والثابتة: أنهي طريقة"},blocks:[{t:"eq",tex:["K_c = \\tfrac34\\,\\dfrac{I_c}{h},\\qquad K_b = \\tfrac12\\,\\dfrac{I_b}{L},\\qquad DF_c = \\dfrac{K_c}{K_c + K_b}","M_F = M_{fe}\\,DF_c,\\qquad X_{2h} = \\dfrac{M_F}{h},\\qquad X_{fixed} = \\dfrac{M_F + M_F/2}{h}","\\delta_{10} + X\\,\\delta_{11} = 0,\\qquad M = M_0 + X\\,M_1"],caption:{en:"First line: the stiffnesses of a symmetric frame — a hinged column ¾I_c/h (a fixed one I_c/h), the beam ½I_b/L, since its far end turns by the same amount the other way. Second line: a straight symmetric frame, one balance at the knee. Third line: a gable, by virtual work with the thrust X as the redundant; a fixed gable approximately — a hinge at H/3 in each column, and with the time short hinges at L/5 in the rafters as well (next section).",ar:"السطر الأول: جساءات الإطار المتماثل — العمود المفصلي ¾I_c/h (والثابت I_c/h)، والكمرة ½I_b/L، لأن طرفها البعيد بيلف بنفس القيمة في الاتجاه التاني. السطر التاني: إطار مستقيم متماثل، توازن واحد عند الركن. السطر التالت: جمالوني، بالشغل الافتراضي والدفع X هو المجهول الزائد؛ والجمالوني الثابت تقريباً — مفصلة عند H/3 في كل عمود، ولو الوقت ضيق مفصلات عند L/5 في الكمرات المائلة كمان (الجزء اللي بعده)."}},{t:"note",tone:"info",text:{en:"The loads reach the frame as in the indeterminate-systems episode: every secondary beam brings R = w_a·S (its load per metre times the frame spacing), and three or more of them are smeared into w = o.w. + ΣP/L. ΣP counts only the beams inside the span: the two beams over the knees send their reactions straight down the columns and add to Y alone. Smearing is the standard hand route and fits best when the loads are roughly equal and evenly spaced; a few large loads near the quarter points have a larger fixed-end moment, ΣPab²/L², than their smeared value — worth a glance when they dominate.",ar:"الأحمال بتوصل للإطار زي حلقة حل الأنظمة غير المحددة: كل كمرة متشالة بتجيب R = w_a·S (حملها لكل متر في المسافة بين الإطارات)، ولو هما تلاتة أو أكتر بيتفرشوا لـ w = o.w. + ΣP/L. والـ ΣP بتعد الكمرات اللي جوه البحر بس: الكمرتين اللي فوق الأركان ردود أفعالهم بتنزل في الأعمدة على طول وبتزوّد Y بس. والفرش هو الطريق اليدوي المعتاد، وأنسب ما يكون لما الأحمال تبقى متساوية تقريباً ومتوزعة بانتظام؛ أما كام حمل كبير قريب من ربع البحر فعزم تثبيتهم ΣPab²/L² أكبر من قيمتهم المفروشة — تستاهل نظرة لما يكونوا هما الغالبين."}},{t:"p",text:{en:"**Loads, worked.** A 20 m frame, frames 6 m apart, secondary beams 250 × 600 ($1.4\\times0.25\\times0.6\\times25 = 5.25$ kN/m) every 2.5 m under a slab of 9.0 kN/m²: an inner beam carries $5.25 + 9.0\\times2.5 = 27.75$ kN/m and brings $R = 27.75\\times6 = 166.5$ kN; a beam over a knee carries $5.25 + 9.0\\times1.25 = 16.5$ kN/m and puts $R = 99.0$ kN straight into the column. With 20 kN/m of frame: $w = 20 + 7\\times166.5/20 = 78.3$ kN/m, $M_{fe} = 2609$ kN·m and $Y = 78.3\\times10 + 99 = 881.8$ kN. Taken one by one, the seven loads give $M_{fe} = 2852$ kN·m — 9.3% more: the price of the shortcut.",ar:"**الأحمال بالأرقام.** إطار 20 م، والإطارات كل 6 م، وكمرات متشالة 250 × 600 ($1.4\\times0.25\\times0.6\\times25 = 5.25$ kN/m) كل 2.5 م تحت بلاطة 9.0 kN/m²: الكمرة الداخلية شايلة $5.25 + 9.0\\times2.5 = 27.75$ kN/m وبتجيب $R = 27.75\\times6 = 166.5$ kN؛ والكمرة اللي فوق الركن شايلة $5.25 + 9.0\\times1.25 = 16.5$ kN/m وبتحط $R = 99.0$ kN في العمود على طول. ومع 20 kN/m وزن الإطار: $w = 20 + 7\\times166.5/20 = 78.3$ kN/m، و $M_{fe} = 2609$ kN·m، و $Y = 78.3\\times10 + 99 = 881.8$ kN. ولو أخدنا السبع أحمال واحد واحد يبقى $M_{fe} = 2852$ kN·m — أكتر بـ 9.3%: ده تمن الاختصار."}},{t:"p",text:{en:"**One balance, worked.** A 16 m two-hinged frame, $h = 6.5$ m, beam and column 350 × 1300 with the beam taken as a rectangle ($I_b = 1.728\\,I_c$), $w = 70$ kN/m: $K_c = 0.75/6.5 = 0.115\\,I_c$, $K_b = 0.5\\times1.728/16 = 0.054\\,I_c$ → $DF_c = 0.681$; $M_{fe} = 70\\times16^2/12 = 1493.3$ kN·m → $M_F = 1017.3$ kN·m, $X = 1017.3/6.5 = 156.5$ kN, $Y = 560$ kN, mid-span $2240 - 1017.3 = 1222.7$ kN·m. Where a **floating bay** — a corridor resting on a corbel of the column — brings its reaction, the column carries it below the corbel only: 120 kN from the corridor make $560 + 120 = 680$ kN there.",ar:"**توازن واحد بالأرقام.** إطار ذو مفصلين 16 م، و $h = 6.5$ م، والكمرة والعمود 350 × 1300 والكمرة متحسبة مستطيل ($I_b = 1.728\\,I_c$)، و $w = 70$ kN/m: $K_c = 0.75/6.5 = 0.115\\,I_c$، و $K_b = 0.5\\times1.728/16 = 0.054\\,I_c$ ← $DF_c = 0.681$؛ و $M_{fe} = 70\\times16^2/12 = 1493.3$ kN·m ← $M_F = 1017.3$ kN·m، و $X = 1017.3/6.5 = 156.5$ kN، و $Y = 560$ kN، ونص البحر $2240 - 1017.3 = 1222.7$ kN·m. ولو **باكية عائمة** — ممر راكب على كابولي قصير من العمود — بتجيب رد فعلها، العمود بيشيله تحت الكابولي القصير بس: 120 kN من الممر بيخلّوا القوة هناك $560 + 120 = 680$ kN."}},{t:"p",text:{en:"**Special cases.** When the live load and the floor cover come as one lumped value, one factor covers the whole slab load: $w_s = 1.5\\,(t_s\\gamma_c + L.L. + F.C.)$, e.g. $1.5\\,(0.12\\times25 + 3.0) = 9.0$ kN/m². A roof on only four corner columns gets two frames along its long sides, and the secondary beams span between them as simple beams: $R = w_a L/2$ (a beam of 25 kN/m over 10 m brings 125 kN), not $w_a S$. A two-way panel whose short side lies on the frame beam loads it directly: $w_e = o.w. + (\\Sigma A/L)\\,w_s$, where $\\Sigma A$ adds up the triangles ($L_s^2/4$ each) the panels hand to the frame — ten panels with a 4 m short side along a 20 m frame give $\\Sigma A/L = 40/20 = 2.0$ m, so with 18 kN/m of frame and 9.0 kN/m² of slab $w_e = 18 + 2.0\\times9.0 = 36$ kN/m. A hollow-block roof resting on the frames adds its rib load per metre of width times the slab span (the hollow-block episode). The secondary beams under two-way panels take the usual trapezoid and triangle shares, $C_a = 1 - L_s/(2L)$ and 0.5 (the loads episode).",ar:"**حالات خاصة.** لو الحمل الحي والتشطيبات جايين قيمة واحدة مجمّعة، معامل واحد بيغطي حمل البلاطة كله: $w_s = 1.5\\,(t_s\\gamma_c + L.L. + F.C.)$، مثلاً $1.5\\,(0.12\\times25 + 3.0) = 9.0$ kN/m². والسقف اللي على أربع أعمدة في الأركان بس بياخد إطارين على ضلعيه الطوال، والكمرات المتشالة بتشيل بينهم ككمرات بسيطة: $R = w_a L/2$ (كمرة 25 kN/m على 10 م بتجيب 125 kN)، مش $w_a S$. والباكية اللي في اتجاهين وضلعها القصير على كمرة الإطار بتحمّلها على طول: $w_e = o.w. + (\\Sigma A/L)\\,w_s$، و $\\Sigma A$ مجموع المثلثات ($L_s^2/4$ لكل واحد) اللي البواكي بتسلّمها للإطار — عشر بواكي ضلعها القصير 4 م على طول إطار 20 م بيدّوا $\\Sigma A/L = 40/20 = 2.0$ م، فمع 18 kN/m وزن إطار و 9.0 kN/m² بلاطة $w_e = 18 + 2.0\\times9.0 = 36$ kN/m. وسقف الهوردي اللي راكب على الإطارات بيزوّد حمل الأعصاب لكل متر عرض مضروب في بحر البلاطة (حلقة البلاطات الهوردي). والكمرات المتشالة تحت البواكي اللي في اتجاهين بتاخد نصيبها المعتاد من الحمل شبه المنحرف والمثلثي، $C_a = 1 - L_s/(2L)$ و 0.5 (حلقة الأحمال)."}},{t:"p",text:{en:"An **edge frame** has its slab on one side only (an L-section); for its stiffness the beam is simply taken as the rectangle $b\\times t$ — 400 × 1500 gives $I_b = 0.4\\times1.5^3/12 = 0.1125$ m⁴. A gable whose two eaves differ a little in level is idealised as symmetric for the hand solution. Along a rafter at slope θ the knee forces $X$ and $V$ resolve into $N = X\\cos\\theta + V\\sin\\theta$ and $Q = V\\cos\\theta - X\\sin\\theta$: with $X = 150$ kN, $V = 420$ kN and θ = 15°, $N = 253.6$ kN and $Q = 366.9$ kN at the knee.",ar:"**الإطار الطرفي** بلاطته من ناحية واحدة بس (قطاع L)؛ وفي حساب جساءته الكمرة بتتاخد ببساطة مستطيل $b\\times t$ — مقاس 400 × 1500 بيدّي $I_b = 0.4\\times1.5^3/12 = 0.1125$ m⁴. والجمالوني اللي ركنيه مختلفين شوية في المنسوب بيتحل يدوي على إنه متماثل. وعلى طول كمرة مائلة بميل θ، قوى الركن $X$ و $V$ بتتحلل لـ $N = X\\cos\\theta + V\\sin\\theta$ و $Q = V\\cos\\theta - X\\sin\\theta$: بـ $X = 150$ kN، و $V = 420$ kN، و θ = 15°، يبقى $N = 253.6$ kN و $Q = 366.9$ kN عند الركن."}},{t:"p",text:{en:"The lab puts a 2 m rise on the 18 m frames. **Two-hinged**: virtual work gives $X = 141.0$ kN, the knee 987.3 and the ridge 1160.6 kN·m; the stiffness method 984.4 and 1164.3 kN·m. **Fixed**: the H/3 hinge gives 1182.9 at the knee, 591.5 at the base and 740.1 at the ridge; the exact frame 1137.1, 753.6 and 752.6 kN·m — the base is underestimated, because the knees spread as well as turn.",ar:"المعمل بيحط ارتفاع 2 م على إطارات الـ 18 م. **ذو مفصلين**: الشغل الافتراضي بيدّي $X = 141.0$ kN، والركن 987.3 والتاج 1160.6 kN·m؛ وطريقة الجساءة 984.4 و 1164.3 kN·m. **ثابت**: مفصلة H/3 بتدّي 1182.9 عند الركن و 591.5 عند القاعدة و 740.1 عند التاج؛ والإطار المضبوط 1137.1 و 753.6 و 752.6 kN·m — القاعدة متقدّرة بأقل من الحقيقة، لأن الأركان بتفتح كمان مش بتلف بس."}},{t:"lab",lab:"frame",height:480,props:{template:"framefamily",params:{f:2},lockTemplate:!0,defaultTab:"hand",missions:s},caption:{en:"The 18 m gable frames: the Hand method tab picks statics, virtual work or the H/3 hinge by the system you choose.",ar:"الإطارات الجمالونية 18 م: تبويب الحل اليدوي بيختار الاتزان أو الشغل الافتراضي أو مفصلة H/3 حسب النظام اللي تختاره."}},{t:"quiz",q:{kind:"num",q:{en:"A straight fixed frame: M_F = 900 kN·m at the knee, h = 6 m. Horizontal reaction X (kN)?",ar:"إطار ثابت مستقيم: M_F = 900 kN·m عند الركن، و h = 6 م. رد الفعل الأفقي X (kN)؟"},answer:225,tol:.003,unit:"kN",explain:{en:"$M_{base} = 450$ kN·m, $X = (900 + 450)/6 = 225$ kN.",ar:"$M_{base} = 450$ kN·m، و $X = (900 + 450)/6 = 225$ kN."}}}]},{id:"approx",title:{en:"Approximate solutions when time is short",ar:"الحلول التقريبية لما الوقت يضيق"},blocks:[{t:"p",text:{en:"When there is no time for the exact method — in an exam, or for a first check — each frame is made determinate by hinges assumed where its moment is nearly zero. All four use the same beam hinges, $L/5$ from each knee measured on plan: the middle $3L/5$ hangs as a simple beam on two short cantilevers, and the knee takes $0.08\\,wL^2$.",ar:"لما مفيش وقت للطريقة المضبوطة — في امتحان، أو لمراجعة أولية — كل إطار بيتعمل محدد بمفصلات بنفترضها في الأماكن اللي عزمه فيها قريب من الصفر. والأربعة بيستخدموا نفس مفصلات الكمرة، على بعد $L/5$ من كل ركن مقاسة على المسقط: الـ $3L/5$ اللي في النص بتتعلّق ككمرة بسيطة على كابوليين قصيرين، والركن بياخد $0.08\\,wL^2$."}},{t:"steps",items:[{en:"**Two-hinged, straight**: hinges at $L/5$ in the beam. $M_{knee} = 0.08\\,wL^2$, $M_{mid} = 0.045\\,wL^2$, $X = M_{knee}/H$.",ar:"**ذو مفصلين، مستقيم**: مفصلات عند $L/5$ في الكمرة. $M_{knee} = 0.08\\,wL^2$، و $M_{mid} = 0.045\\,wL^2$، و $X = M_{knee}/H$."},{en:"**Fixed, straight**: add a hinge in each column $H/3$ above the base — a two-hinged frame $2H/3$ high remains: $X = 0.08\\,wL^2/(2H/3) = 0.12\\,wL^2/H$ and $M_{base} = X\\,H/3 = 0.04\\,wL^2 = M_{knee}/2$.",ar:"**ثابت، مستقيم**: زوّد مفصلة في كل عمود على ارتفاع $H/3$ فوق القاعدة — يفضل إطار ذو مفصلين ارتفاعه $2H/3$: $X = 0.08\\,wL^2/(2H/3) = 0.12\\,wL^2/H$ و $M_{base} = X\\,H/3 = 0.04\\,wL^2 = M_{knee}/2$."},{en:"**Two-hinged gable** of rise $f$: hinges in the rafters at $L/5$ on plan, $h + 0.4f$ above the base hinges: $X = 0.08\\,wL^2/(h + 0.4f)$, $M_{knee} = X\\,h$, $M_{ridge} = wL^2/8 - X\\,(h + f)$.",ar:"**جمالوني ذو مفصلين** ارتفاعه $f$: مفصلات في الكمرات المائلة عند $L/5$ على المسقط، على ارتفاع $h + 0.4f$ فوق مفصلات القواعد: $X = 0.08\\,wL^2/(h + 0.4f)$، و $M_{knee} = X\\,h$، و $M_{ridge} = wL^2/8 - X\\,(h + f)$."},{en:"**Fixed gable**: both sets of hinges at once, so it is fully determinate: $X = 0.08\\,wL^2/(2h/3 + 0.4f)$, $M_{knee} = X\\cdot2h/3$, $M_{base} = X\\,h/3$, $M_{ridge} = wL^2/8 - X\\,(2h/3 + f)$.",ar:"**جمالوني ثابت**: المجموعتين من المفصلات مع بعض، فيبقى محدد تماماً: $X = 0.08\\,wL^2/(2h/3 + 0.4f)$، و $M_{knee} = X\\cdot2h/3$، و $M_{base} = X\\,h/3$، و $M_{ridge} = wL^2/8 - X\\,(2h/3 + f)$."}]},{t:"eq",tex:["M_{knee} = 0.08\\,wL^2,\\qquad M_{mid} = 0.045\\,wL^2","X = \\dfrac{0.08\\,wL^2}{H_e},\\qquad H_e = H,\\quad \\tfrac23 H,\\quad h + 0.4f,\\quad \\tfrac23 h + 0.4f"],caption:{en:"H_e = height of the beam hinges above the lower hinges: two-hinged straight, fixed straight (column hinges at H/3), two-hinged gable, fixed gable.",ar:"H_e = ارتفاع مفصلات الكمرة فوق المفصلات اللي تحتها: ذو مفصلين مستقيم، وثابت مستقيم (مفصلات الأعمدة عند H/3)، وجمالوني ذو مفصلين، وجمالوني ثابت."}},{t:"note",tone:"warn",text:{en:"The assumed hinges ignore the stiffness of the members, so these answers are very approximate: keep them for when the time runs out, and check them before you trust them.",ar:"المفصلات المفترضة بتتجاهل جساءة العناصر، فالنتايج دي تقريبية جداً: استخدمها بس لما الوقت يخلص، وراجعها قبل ما تثق فيها."}},{t:"p",text:{en:"**The lab frames** (18 m, 7 m columns, 60 kN/m; $0.08\\,wL^2 = 1555.2$ kN·m). Two-hinged: $M_{knee} = 1555.2$ and $M_{mid} = 874.8$ kN·m, $X = 222.2$ kN, against the exact 985.2 and 1444.8. Fixed: $X = 1555.2/4.667 = 333.3$ kN, the base 777.6 kN·m, against 1253.0, 1177.0 and 612.3. With the 2 m rise, two-hinged: $X = 1555.2/7.8 = 199.4$ kN, the knee 1395.7 and the ridge 635.5 kN·m (exact 984.4 and 1164.3); fixed: $X = 1555.2/5.467 = 284.5$ kN, knee 1327.6, base 663.8, ridge 533.4 kN·m (exact 1137.1, 753.6, 752.6). The hinges overload the knees and starve the span: hinges at $L/5$ act as if the columns held the beam ends almost fixed, but these columns turn with the knees, so the true zero points lie nearer the knees than $L/5$.",ar:"**إطارات المعمل** (18 م، وأعمدة 7 م، و 60 kN/m؛ $0.08\\,wL^2 = 1555.2$ kN·m). ذو مفصلين: $M_{knee} = 1555.2$ و $M_{mid} = 874.8$ kN·m، و $X = 222.2$ kN، قصاد المضبوط 985.2 و 1444.8. ثابت: $X = 1555.2/4.667 = 333.3$ kN، والقاعدة 777.6 kN·m، قصاد 1253.0 و 1177.0 و 612.3. وبارتفاع الجمالون 2 م، ذو مفصلين: $X = 1555.2/7.8 = 199.4$ kN، والركن 1395.7 والقمة 635.5 kN·m (المضبوط 984.4 و 1164.3)؛ وثابت: $X = 1555.2/5.467 = 284.5$ kN، والركن 1327.6، والقاعدة 663.8، والقمة 533.4 kN·m (المضبوط 1137.1 و 753.6 و 752.6). المفصلات بتحمّل الأركان زيادة وبتظلم البحر: المفصلات عند $L/5$ بتشتغل كأن الأعمدة ماسكة أطراف الكمرة شبه ثابتة، بس الأعمدة دي بتلف مع الأركان، فنقط الصفر الحقيقية أقرب للأركان من $L/5$."}},{t:"p",text:{en:"**Why the fixed gable above all.** Its knees spread as it bends, so a moment distribution would need sway corrections, and virtual work has two redundants to find — the thrust and the base moment — which is long by hand. With no time, the two sets of hinges make it determinate; with time, the $H/3$ hinge alone and virtual work on the two-hinged gable that remains (the section above) come much closer.",ar:"**ليه الجمالوني الثابت بالذات.** أركانه بتفتح وهو بينحني، فتوزيع العزوم هيحتاج تصحيحات للإزاحة الجانبية (Sway)، والشغل الافتراضي فيه مجهولين زيادة — الدفع وعزم القاعدة — وده طويل يدوي. ولو مفيش وقت، المجموعتين من المفصلات بيخلّوه محدد؛ ولو فيه وقت، مفصلة $H/3$ لوحدها والشغل الافتراضي على الجمالوني ذو المفصلين اللي بيفضل (الجزء اللي فوق) بيقرّبوا أكتر بكتير."}},{t:"quiz",q:{kind:"num",q:{en:"Approximate fixed straight frame: w = 50 kN/m, L = 20 m, H = 6 m. Horizontal reaction X (kN)?",ar:"إطار ثابت مستقيم بالطريقة التقريبية: w = 50 kN/m، و L = 20 م، و H = 6 م. رد الفعل الأفقي X (kN)؟"},answer:400,tol:.003,unit:"kN",explain:{en:"$0.08\\times50\\times20^2 = 1600$ kN·m at the knee; $X = 1600/(2\\times6/3) = 400$ kN, and the base $400\\times2 = 800$ kN·m $= 1600/2$.",ar:"$0.08\\times50\\times20^2 = 1600$ kN·m عند الركن؛ و $X = 1600/(2\\times6/3) = 400$ kN، والقاعدة $400\\times2 = 800$ kN·m $= 1600/2$."}}}]},{id:"hinges",title:{en:"Real hinges and the footing shift",ar:"المفصلات الحقيقية وترحيل القواعد"},blocks:[{t:"p",text:{en:"A hinged frame leans on its footings with the thrust $X$ at the hinge, $t_1 + t_2$ above the footing base (footing + plain concrete) — a permanent moment on the footing. Shift the footing **outwards**, against $X$, until the resultant passes through its centre; the shift is usually 0.25–0.50 m. A fixed frame sends its base moment instead: shift the footing against the moment, $e = M/P$. At a fixed base the inner face is in tension under that moment: its bars, $A_{s4}$, are L-bars hooked into the footing and run up the inner face. The outer face is in compression there and gets **starter bars only**, lapping the outer bars that come down from the knee; every lap above the footing is at least $40\\Phi$ **and** at least 1.0 m (Ø22: $40\\times22 = 880$ mm → 1.0 m; Ø28: 1.12 m). A **tie between the footings**, at hinge level, takes the thrust itself: the footings then need no shift, and the frame still works as a two-hinged frame.",ar:"الإطار المفصلي بيتسند على قواعده بالدفع $X$ عند المفصلة، واللي فوق أسفل القاعدة بـ $t_1 + t_2$ (القاعدة + الخرسانة العادية) — يعني عزم دايم على القاعدة. رحّل القاعدة **لبره**، عكس $X$، لحد ما المحصلة تعدّي من نصها؛ والترحيل غالباً 0.25–0.50 م. والإطار الثابت بيبعت عزم قاعدته بدل كده: رحّل القاعدة عكس العزم، $e = M/P$. وعند الركيزة الثابتة الوش الداخلي بيبقى شد تحت العزم ده: حديده $A_{s4}$ أسياخ على شكل L متجنشة في القاعدة وطالعة على الوش الداخلي. والوش الخارجي بيبقى ضغط هناك فبياخد **أشاير بس**، بتعمل وصلة بالتراكب مع الحديد الخارجي النازل من الركن؛ وأي وصلة فوق القاعدة طولها على الأقل $40\\Phi$ **وكمان** على الأقل 1.0 م (Ø22: $40\\times22 = 880$ مم ← 1.0 م؛ Ø28: 1.12 م). و**الشداد بين القواعد**، عند منسوب المفصلات، بياخد الدفع بنفسه: القواعد ساعتها مش محتاجة ترحيل، والإطار بيفضل شغال إطار ذو مفصلين."}},{t:"eq",tex:["e = \\dfrac{X\\,(t_1 + t_2)}{Y}","e = \\dfrac{M_{base}}{P}"],caption:{en:"First line: hinged base, shifted outwards; second line: fixed base, shifted against the base moment.",ar:"السطر الأول: ركيزة مفصلية، الترحيل لبره؛ والسطر التاني: ركيزة ثابتة، الترحيل عكس عزم القاعدة."}},{t:"p",text:{en:"**Examples.** $X = 180$ kN, $Y = 720$ kN, a 0.9 m footing on 0.3 m of plain concrete: $e = 180\\times1.2/720 = 0.30$ m outwards. A fixed base with $M = 400$ kN·m and $P = 1000$ kN: $e = 0.40$ m against the moment.",ar:"**أمثلة.** $X = 180$ kN، و $Y = 720$ kN، وقاعدة 0.9 م على 0.3 م خرسانة عادية: $e = 180\\times1.2/720 = 0.30$ م لبره. وركيزة ثابتة بعزم $M = 400$ kN·m و $P = 1000$ kN: $e = 0.40$ م عكس العزم."}},{t:"quiz",q:{kind:"num",q:{en:"Hinged frame: X = 120 kN, t₁ + t₂ = 1.1 m, Y = 480 kN. Footing shift e (m)?",ar:"إطار مفصلي: X = 120 kN، و t₁ + t₂ = 1.1 م، و Y = 480 kN. ترحيل القاعدة e (م)؟"},answer:.275,tol:.003,unit:"m",explain:{en:"$120\\times1.1/480 = 0.275$ m, outwards.",ar:"$120\\times1.1/480 = 0.275$ م، لبره."}}}]},{id:"sky",title:{en:"Frames with sky-lights",ar:"إطارات بشخشيخة (Sky-light)"},blocks:[{t:"steps",items:[{en:"**Slab left out** over part of the beam and glazed: the beam loses its flange there, so its inertia is averaged by length (the indeterminate-systems episode).",ar:"**البلاطة متشالة** على جزء من الكمرة ومتقفلة إزاز: الكمرة بتخسر الشفة هناك، فعزم قصورها بيتحسب متوسط بالطول (حلقة حل الأنظمة غير المحددة)."},{en:"**A raised lantern on posts**: short posts stand on the frame beam and carry a light raised roof — for the frame, two point loads instead of the slab they replace.",ar:"**شخشيخة مرفوعة (فانوس) على قوائم**: قوائم قصيرة واقفة على كمرة الإطار وشايلة سقف مرفوع خفيف — وبالنسبة للإطار دول حملين مركزين بدل البلاطة اللي اتشالت."},{en:"**A cranked beam**: the frame beam itself steps up to form the opening; the knee of the step is detailed like a frame knee.",ar:"**كمرة متكسرة**: كمرة الإطار نفسها بتطلع درجة علشان تعمل الفتحة؛ وركن الدرجة بيتسلّح زي ركن الإطار."}]},{t:"eq",tex:["I_b = \\dfrac{I_{b1}\\cdot 2L_1 + I_{b2}\\cdot L_2}{2L_1 + L_2}","M_{fe} = \\dfrac{2PL}{9}"],caption:{en:"First line: averaged inertia (2L₁ with slab, L₂ without). Second line: two post loads P at the third points.",ar:"السطر الأول: عزم القصور المتوسط (2L₁ ببلاطة، و L₂ من غيرها). السطر التاني: حملين P من القوائم عند التلت."}},{t:"p",text:{en:"**Example.** An 18 m frame with a lantern over its middle 6 m on two posts, $P = 120$ kN each: $M_{fe} = 2\\times120\\times18/9 = 480$ kN·m — a third more than the same 240 kN spread over the span ($wL^2/12 = 13.33\\times18^2/12 = 360$ kN·m). Point loads near the middle hurt the span more than a spread load of the same size.",ar:"**مثال.** إطار 18 م عليه فانوس فوق الـ 6 م اللي في النص على قائمين، $P = 120$ kN لكل واحد: $M_{fe} = 2\\times120\\times18/9 = 480$ kN·m — أكتر بالتلت من نفس الـ 240 kN مفروشين على البحر ($wL^2/12 = 13.33\\times18^2/12 = 360$ kN·m). الأحمال المركزة قريب من النص بتتعب البحر أكتر من حمل مفروش بنفس القيمة."}},{t:"p",text:{en:"A two-hinged frame with a sky-light, straight or gable, is kept to **12–20 m**: the open bay takes the flange away and adds the post loads. Under the opening the beam has no slab, so its mid-span section is designed as a **rectangle**, not a T. The lantern itself takes one of two forms. Over a **three-hinged** frame it is a small three-hinged frame too: its posts stand on hinges on the main beam, and its own 2 cm crown gap lies right above the main crown hinge (over a three-hinged gable, a small gable). Over a **two-hinged or fixed** frame the posts and the lantern roof form a small rigid frame cast with the main beam: the post bars are hooked down into the frame beam, and the lantern roof bars are closed as L- and U-bars round its corners, often over short 0.5 m cantilevers.",ar:"الإطار ذو المفصلين اللي فيه شخشيخة، مستقيم أو جمالوني، بيتحدد بـ **12–20 م**: الباكية المفتوحة بتشيل الشفة وبتزوّد أحمال القوائم. وتحت الفتحة الكمرة مفيش عليها بلاطة، فقطاع نص البحر بيتصمم **مستطيل**، مش T. والشخشيخة نفسها ليها شكلين. فوق الإطار **ثلاثي المفصلات** بتبقى هي كمان إطار صغير ثلاثي المفصلات: قوائمها واقفة على مفصلات فوق الكمرة الرئيسية، وفاصل التاج بتاعها (2 سم) فوق مفصلة التاج الرئيسية بالظبط (وفوق الجمالوني ثلاثي المفصلات، جمالون صغير). وفوق الإطار **ذو المفصلين أو الثابت** القوائم وسقف الشخشيخة بيعملوا إطار صغير جاسئ مصبوب مع الكمرة الرئيسية: حديد القوائم بينزل متجنش في كمرة الإطار، وحديد سقف الشخشيخة بيتقفل على شكل L و U حوالين أركانها، وكتير بكوابيل قصيرة 0.5 م."}},{t:"p",text:{en:"**The post load.** Three beams meet at the head of a post: the transverse lantern beam on the post line, simply supported across the lantern ($R_1 = w_a L/2$); the longitudinal edge beam of the lantern roof with its cantilever strip ($R_2 = w_a S$); and the edge beam of the main roof along the opening ($R_3 = w_a S$). So $P_{post} = R_1 + R_2 + R_3$. **Example**: a 5 m lantern on frames 6 m apart, with beams of 18, 21 and 15 kN/m: $R_1 = 18\\times5/2 = 45$, $R_2 = 21\\times6 = 126$, $R_3 = 15\\times6 = 90$ → $P = 261$ kN on each post.",ar:"**حمل القائم.** تلات كمرات بيتقابلوا عند راس القائم: كمرة الشخشيخة العرضية اللي على خط القوائم، بسيطة الارتكاز على عرض الشخشيخة ($R_1 = w_a L/2$)؛ والكمرة الطرفية الطولية لسقف الشخشيخة بشريحة الكابولي بتاعتها ($R_2 = w_a S$)؛ والكمرة الطرفية للسقف الرئيسي على طول الفتحة ($R_3 = w_a S$). يعني $P_{post} = R_1 + R_2 + R_3$. **مثال**: شخشيخة 5 م على إطارات كل 6 م، وكمرات 18 و 21 و 15 kN/m: $R_1 = 18\\times5/2 = 45$، و $R_2 = 21\\times6 = 126$، و $R_3 = 15\\times6 = 90$ ← $P = 261$ kN على كل قائم."}},{t:"p",text:{en:"**Saw-tooth roofs on frames.** When the glazing runs **perpendicular** to the frames, the Y-beams and the end beams span between the frames and sit on their beams; each end beam hands its frame $R_{VL} = w_{VL}\\,S$ downwards and $R_{HL} = X\\,S$ **outwards** at both knees (the slab thrust at one end, the push of the posts at the other), so the normal force in the frame beam is its own thrust less $R_{HL}$. **Example:** $X = 4.5$ kN/m on frames 6 m apart: $R_{HL} = 27$ kN; with a thrust of 150 kN the frame beam keeps $150 - 27 = 123$ kN of compression. When the glazing runs **parallel** to the frames, the windows are normally vertical; inclined windows push every frame sideways, out of its plane — the inner frames receive the push from both sides and hardly notice it, but the first and the last frame get it from one side only. Either tie the roof between the frames, in its own plane, every few windows, or make the two end frames **fixed**, $b = 500$ mm, and design them for **biaxial bending**.",ar:"**الأسقف المنشارية على الإطارات.** لما الشبابيك تمشي **عمودي** على الإطارات، كمرات Y والكمرات الطرفية بتشيل بين الإطارات وقاعدة على كمراتها؛ وكل كمرة طرفية بتسلّم إطارها $R_{VL} = w_{VL}\\,S$ لتحت و $R_{HL} = X\\,S$ **لبره** عند الركنين (دفع البلاطة عند طرف، وزقة القوائم عند الطرف التاني)، فالقوة العمودية في كمرة الإطار بتبقى دفعه هو ناقص $R_{HL}$. **مثال:** $X = 4.5$ kN/m على إطارات كل 6 م: $R_{HL} = 27$ kN؛ ومع دفع 150 kN كمرة الإطار بيفضل فيها $150 - 27 = 123$ kN ضغط. ولما الشبابيك تمشي **موازية** للإطارات، الشبابيك عادةً رأسية؛ والشبابيك المايلة بتزق كل إطار جنب، خارج مستواه — الإطارات اللي في النص بتاخد الزقة من الناحيتين فمابتحسّش بيها تقريباً، لكن أول وآخر إطار بياخدوها من ناحية واحدة بس. يا إما تربط السقف بين الإطارات، في مستواه، كل كام شباك، يا إما تخلّي الإطارين الطرفيين **ثابتين الركائز**، بعرض $b = 500$ مم، وتصممهم على **عزم في اتجاهين**."}},{t:"quiz",q:{kind:"num",q:{en:"Posts at the third points carry P = 90 kN each, span 15 m. Fixed-end moment (kN·m)?",ar:"قوائم عند التلت شايلة P = 90 kN كل واحد، والبحر 15 م. عزم التثبيت (kN·m)؟"},answer:300,tol:.003,unit:"kN·m",explain:{en:"$2\\times90\\times15/9 = 300$ kN·m.",ar:"$2\\times90\\times15/9 = 300$ kN·m."}}}]},{id:"levels",title:{en:"Two roof levels: posts, hangers and roof steps",ar:"سقفين بمنسوبين: القوائم والمعلّقات ودرجات السقف"},blocks:[{t:"p",text:{en:"When one frame carries roofs at two levels, the level difference Δ decides how. **Δ ≤ 2.0 m**: the frame carries both slabs directly — the high slab on top of its beam, the low one at its soffit, glazing between — so the beam must be at least $t \\ge \\Delta + t_{s,low}$ deep; the low slabs are carried on **inverted beams**, so they do not deepen the frame any further. Where the level changes at every frame, each bay's slab bars are hooked into its own two frames. **Δ > 2.0 m**: a still deeper frame would cost too much, so the frame carries one slab directly and the other on a beam that stands on **posts** (tied together along the frame by a tie beam) or hangs from **hangers**; the frame depth then no longer depends on Δ, and the ribs of a hollow-block slab always need that beam to sit on. **Example**: a 1.4 m step with a 120 mm low slab: $t \\ge 1.4 + 0.12 = 1.52$ m — the beam is made 1.55 m deep even if its depth rule asks for only 1.35 m.",ar:"لما إطار واحد يشيل سقفين بمنسوبين، فرق المنسوب Δ هو اللي بيقرر إزاي. **Δ ≤ 2.0 م**: الإطار بيشيل البلاطتين على طول — البلاطة العالية فوق كمرته، والواطية عند بطنها، وبينهم إزاز — فعمق الكمرة لازم يبقى على الأقل $t \\ge \\Delta + t_{s,low}$؛ والبلاطات الواطية بتتشال على **كمرات مقلوبة** علشان ماتزوّدش عمق الإطار أكتر. ولو المنسوب بيتغيّر عند كل إطار، حديد بلاطة كل باكية بيتجنش في الإطارين بتوعها. **Δ > 2.0 م**: إطار أعمق من كده هيكلّف كتير، فالإطار بيشيل بلاطة على طول والتانية على كمرة واقفة على **قوائم** (مربوطة ببعض على طول الإطار بكمرة تربيط) أو متعلّقة في **معلّقات**؛ وعمق الإطار ساعتها مابقاش معتمد على Δ، وأعصاب البلاطة الهوردي دايماً محتاجة الكمرة دي تقعد عليها. **مثال**: درجة 1.4 م وبلاطة واطية 120 مم: $t \\ge 1.4 + 0.12 = 1.52$ م — الكمرة بتتعمل بعمق 1.55 م حتى لو قاعدة العمق بتطلب 1.35 م بس."}},{t:"table",head:[{en:"Clear height of the post H₀",ar:"الارتفاع الصافي للقائم H₀"},{en:"Behaves as",ar:"بيشتغل كـ"},{en:"Section",ar:"القطاع"},{en:"Bars",ar:"الحديد"}],rows:[["≤ 2.5 m",{en:"a short column",ar:"عمود قصير"},"250 × 250","4Ø12"],["2.5–4.0 m",{en:"a long column",ar:"عمود طويل"},{en:"still 250 × 250",ar:"برضه 250 × 250"},"8Ø12"],["> 4.0 m",{en:"not preferred",ar:"حل غير مفضل"},{en:"b × b, b = width of the system that carries it",ar:"b × b، و b = عرض النظام اللي شايله"},"8Ø12"]],caption:{en:"Posts on a frame beam. A hanger is in tension and cannot buckle: 250 × 250 at any height, 4Ø12 when it holds only a tie, 8Ø12 when it carries a beam, its bars running into that beam whether it is dropped or inverted.",ar:"القوائم على كمرة الإطار. والمعلّق شغال شد ومش ممكن يحصله انبعاج: 250 × 250 بأي ارتفاع، و 4Ø12 لو شايل شداد بس، و 8Ø12 لو شايل كمرة، وحديده داخل في الكمرة دي سواء كانت ساقطة أو مقلوبة."}},{t:"p",text:{en:"Given the choice, a level stands on posts; it hangs only when a post would be taller than 4.0 m — a 5 m post is a poor answer, though not a wrong one. Typical answers: a flat roof beside a raised inclined one → a straight two-hinged frame under the flat part with the inclined slab on posts (moment distribution); the same roof where nothing may stand between the two levels → a two-hinged gable with the flat slab hung from it (virtual work); a raised middle with free space under it → a two-hinged polygonal (trapezoidal) frame with the side slabs on hangers (virtual work).",ar:"لو فيه اختيار، المنسوب بيقف على قوائم؛ وبيتعلّق بس لو القائم هيبقى أطول من 4.0 م — والقائم 5 م حل سيئ، بس مش غلط. وحلول نموذجية: سقف أفقي جنب سقف مايل أعلى منه ← إطار ذو مفصلين مستقيم تحت الجزء الأفقي والبلاطة المايلة على قوائم (توزيع العزوم)؛ ونفس السقف لو ممنوع يقف أي عنصر بين المنسوبين ← جمالوني ذو مفصلين والبلاطة الأفقية متعلّقة فيه (الشغل الافتراضي)؛ ونص مرفوع ولازم اللي تحته يفضل فاضي ← إطار مضلع (شبه منحرف) ذو مفصلين والبلاطات الجانبية على معلّقات (الشغل الافتراضي)."}},{t:"p",text:{en:"**Roof steps between two halls.** Two **girders** at different levels on a shared column: each girder is simple; the shared column takes $R$ at its top and $R$ again at the lower roof — $2R$ at its base — and runs on up between the two roofs as the window wall: girders bringing 280 kN each put 560 kN at its base. A **girder beside a frame**: the girder stays simple, and its reaction is only an axial load on the frame column; its bars are hooked into that column, and the girder's outer column carries no moment. **Two frames**: in practice one continuous frame, but by hand they are separated — the tall frame two-hinged (moment distribution), the low frame roller–fixed (virtual work), its beam end resting on a corbel of the tall column (the heavy-frames episode).",ar:"**درجات السقف بين صالتين.** **كمرتين (Girders)** بمنسوبين مختلفين على عمود مشترك: كل كمرة بسيطة؛ والعمود المشترك بياخد $R$ عند راسه و $R$ تاني عند السقف الواطي — $2R$ عند قاعدته — وبيكمّل لفوق بين السقفين كحائط الشبابيك: كمرتين كل واحدة بتجيب 280 kN بيحطوا 560 kN عند قاعدته. و**كمرة جنب إطار**: الكمرة بتفضل بسيطة، ورد فعلها مجرد حمل محوري على عمود الإطار؛ وحديدها بيتجنش في العمود ده، والعمود الخارجي للكمرة مابياخدش عزم. و**إطارين**: في الواقع إطار مستمر واحد، بس يدوي بنفصلهم — الإطار العالي ذو مفصلين (توزيع العزوم)، والواطي متحركة–ثابتة (الشغل الافتراضي)، وطرف كمرته راكب على كابولي قصير من العمود العالي (حلقة الإطارات الثقيلة)."}},{t:"quiz",q:{kind:"mcq",q:{en:"One frame must carry two slabs 3.0 m apart in level. The usual arrangement?",ar:"إطار واحد لازم يشيل بلاطتين فرق منسوبهم 3.0 م. الترتيب المعتاد؟"},options:[{en:"the frame carries one slab; the other sits on a beam on posts (or on hangers)",ar:"الإطار بيشيل بلاطة؛ والتانية على كمرة فوق قوائم (أو على معلّقات)"},{en:"the frame beam is made Δ + t_s ≈ 3.1 m deep and carries both",ar:"كمرة الإطار بتتعمل بعمق Δ + t_s ≈ 3.1 م وتشيل الاتنين"},{en:"the two slabs need two separate frames at every axis",ar:"البلاطتين محتاجين إطارين منفصلين عند كل محور"}],answer:0,explain:{en:"Above 2.0 m the frame would grow too deep; it takes one slab directly and the other stands on posts (tied by a tie beam) or hangs.",ar:"فوق 2.0 م الإطار هيبقى عميق زيادة؛ فبياخد بلاطة على طول والتانية بتقف على قوائم (مربوطة بكمرة تربيط) أو بتتعلّق."}}}]},{id:"multi",title:{en:"Continuous frames: the full distribution table",ar:"الإطارات المستمرة: جدول التوزيع الكامل"},blocks:[{t:"p",text:{en:"A wide hall is covered by frames of several bays: inner columns cut the span and the moments. With more than one joint the single balance is no longer the answer — the joints talk to each other through the carry-overs — so we run the **full moment-distribution table**:",ar:"الصالة العريضة بتتغطى بإطارات كذا باكية: الأعمدة الوسطانية بتقطع البحر والعزوم. ومع أكتر من عقدة التوازن الواحد مابقاش هو الحل — العقد بتكلم بعض عن طريق الانتقالات — فبنعمل **جدول توزيع العزوم الكامل**:"}},{t:"steps",items:[{en:"Stiffness of every member end: beams $I/L$ (far end fixed), columns $I/h$ with a fixed base or $\\tfrac34 I/h$ with a hinged one.",ar:"جساءة كل طرف عضو: الكمرات $I/L$ (الطرف البعيد ثابت)، والأعمدة $I/h$ بقاعدة ثابتة أو $\\tfrac34 I/h$ بقاعدة مفصلية."},{en:"Distribution factors $DF = K/\\Sigma K$ at every joint ($\\Sigma DF = 1$).",ar:"معاملات التوزيع $DF = K/\\Sigma K$ عند كل عقدة ($\\Sigma DF = 1$)."},{en:"Fixed-end moments of every loaded beam, clockwise positive ($-wL^2/12$ at the left end, $+wL^2/12$ at the right).",ar:"عزوم التثبيت لكل كمرة محمّلة، مع عقارب الساعة موجب ($-wL^2/12$ عند الطرف الشمال و $+wL^2/12$ عند اليمين)."},{en:"Balance every joint: each end gets $-DF$ × the unbalance; carry half of it to the far end of beams and fixed columns.",ar:"وازن كل عقدة: كل طرف بياخد $-DF$ × العزم مش المتزن؛ وانقل نصه للطرف البعيد في الكمرات والأعمدة الثابتة."},{en:"Repeat until the carry-overs are negligible, then add up every column of the table.",ar:"كرّر لحد ما الانتقالات تبقى مهملة، وبعدين اجمع كل عمود في الجدول."}]},{t:"p",text:{en:"**Example — the lab frame**: two bays of 12 m on 6 m hinged columns, 60 kN/m, beams 400 × 1000 (T) and columns 400 × 800. $K_b = 0.00393$, $K_c = \\tfrac34 I_c/h = 0.00123$: at an edge joint $DF = 0.761$ (beam) / 0.239 (column), at the inner one 0.432 / 0.432 / 0.136. $M_{fe} = 60\\times12^2/12 = 720$ kN·m. The edge joint balances $0.761\\times720 = 548$ and sends 274 to the inner joint, which stays balanced by symmetry. Result: 172.0 kN·m at the edge knees, 994.0 over the inner column, 536.1 in each span. The stiffness method: 177.5, 978.9 and 539.0 — it also lets the heavily loaded inner column shorten. With three bays the inner joints are no longer balanced by symmetry and the table runs for 17 cycles.",ar:"**مثال — إطار المعمل**: بايكتين 12 م على أعمدة مفصلية 6 م، و 60 kN/m، وكمرات 400 × 1000 (T) وأعمدة 400 × 800. $K_b = 0.00393$، و $K_c = \\tfrac34 I_c/h = 0.00123$: عند عقدة طرفية $DF = 0.761$ (الكمرة) / 0.239 (العمود)، وعند الداخلية 0.432 / 0.432 / 0.136. و $M_{fe} = 60\\times12^2/12 = 720$ kN·m. العقدة الطرفية بتوازن $0.761\\times720 = 548$ وبتبعت 274 للعقدة الداخلية، اللي بتفضل متزنة بالتماثل. النتيجة: 172.0 kN·m عند الأركان الطرفية، و 994.0 فوق العمود الوسطاني، و 536.1 في كل بحر. وطريقة الجساءة: 177.5 و 978.9 و 539.0 — لأنها كمان بتخلّي العمود الوسطاني التقيل يقصر. ومع تلات بواكي العقد الداخلية مابقتش تتوازن بالتماثل والجدول بياخد 17 دورة."}},{t:"lab",lab:"frame",height:480,props:{template:"multibay",lockTemplate:!0,defaultTab:"hand",missions:i},caption:{en:"A continuous frame of equal bays: the Hand method tab prints the distribution table of half the frame.",ar:"إطار مستمر ببواكي متساوية: تبويب الحل اليدوي بيطبع جدول التوزيع لنص الإطار."}},{t:"p",text:{en:"The hand table assumes that the joints do not sway, so the frame must be **symmetric**, and symmetrically loaded: then half of it is enough, its middle joint held fixed on the axis of symmetry — for two equal bays one balance at the edge joint and one carry-over finish the job, and the middle column takes no moment. In that half frame the edge column has $K_{col} = \\tfrac34 I_c/h$ and the beam, its far end now fixed, $K_{beam} = I_b/L$; the span moment is taken at mid-span, $wL^2/8 - (M_1 + M_2)/2$ — for the lab frame $1080 - (172.0 + 994.0)/2 = 497.0$ kN·m (the true maximum, 536.1, lies nearer the edge knee). In concrete, the middle column of a hinged continuous frame tapers from both faces down to its hinge; the top bars over it are staggered on both sides, its own bars run up into the beam and bend into it both ways, and every foot gets crossed hinge dowels. Under the symmetric load it carries $N$ only, yet it is cast rigidly with the beam — it is **not a link member**: it takes the depth of the beam at its head, tapering to $t/2$ at its hinge, and at least $A_{s,total} = 0.8\\%\\,b\\,t$, half on each face ($A_s = A_s'$), anchored $L_d$ into the beam, because unequal live loads on the two bays bend it either way. Under a 400 × 1000 beam: $0.008\\times400\\times1000 = 3200$ mm², 1600 mm² a face → 5Ø22 (1901 mm²) on each face.",ar:"الجدول اليدوي بيفترض إن العقد مابتتحركش جنب، فالإطار لازم يبقى **متماثل** ومحمّل تحميل متماثل: ساعتها نصه بيكفي، وعقدته الوسطانية متثبتة على محور التماثل — وللبايكتين المتساويتين توازن واحد عند العقدة الطرفية وانتقال واحد بيخلّصوا الشغلانة، والعمود الوسطاني مابياخدش عزم. وفي نص الإطار ده العمود الطرفي ليه $K_{col} = \\tfrac34 I_c/h$ والكمرة، وطرفها البعيد بقى ثابت، $K_{beam} = I_b/L$؛ وعزم البحر بيتاخد في نصه، $wL^2/8 - (M_1 + M_2)/2$ — لإطار المعمل $1080 - (172.0 + 994.0)/2 = 497.0$ kN·m (وأكبر قيمة حقيقية، 536.1، أقرب للركن الطرفي). وفي الخرسانة العمود الوسطاني لإطار مستمر مفصلي بيتدرّج من الوشين لحد مفصلته؛ والحديد العلوي فوقه بيتوقف على مراحل من الناحيتين، وحديده هو بيطلع في الكمرة ويتكسّح فيها في الاتجاهين، وكل رجل بتاخد أشاير مفصلة متقاطعة. وتحت الحمل المتماثل شايل $N$ بس، ومع ذلك مصبوب مع الكمرة جاسئ — **مش وصلة**: بياخد عمق الكمرة عند راسه، متدرّج لـ $t/2$ عند مفصلته، وعلى الأقل $A_{s,total} = 0.8\\%\\,b\\,t$، نصهم على كل وش ($A_s = A_s'$)، ومتثبتين $L_d$ جوه الكمرة، لأن الأحمال الحية المختلفة على الباكيتين بتحنيه في اتجاه أو التاني. تحت كمرة 400 × 1000: $0.008\\times400\\times1000 = 3200$ مم²، يعني 1600 مم² لكل وش ← 5Ø22 (1901 مم²) على كل وش."}},{t:"p",text:{en:"**A cantilever outside the column.** Up to $L_c = 2.0$ m it is a **cantilever slab** springing from a longitudinal edge beam B between the frame columns: B is twisted, and its torsion reaches each frame column as a concentrated moment $M = (w_s L_c^2/2)\\,S$ at the level of B. Beyond 2.0 m it becomes a **cantilever frame** — a tapered cantilever beam cast with every column — and B is no longer twisted. Either way the single balance $M_F = M_{fe}\\,DF_c$ no longer holds: the frame is solved by the full table (the cantilever is a member without stiffness that carries its moment $M_c$) or by virtual work. For a symmetric frame a quick estimate is $M_F = M_1 + M_c$, with $M_1 = M_{fe}\\,DF_c$ of the frame without the cantilever. Where an inclined hollow-block roof runs out into a solid cantilever slab, the two overlap at the support, so both are reinforced **per rib** — the top bars of each rib run over the support on into the solid cantilever — and the solid part gets one extra Ø10 between the ribs.",ar:"**كابولي بره العمود.** لحد $L_c = 2.0$ م بيبقى **بلاطة كابولي** طالعة من كمرة طرفية طولية B بين أعمدة الإطارات: الكمرة B بيحصلها لي، وعزم اللي (الالتواء) بتاعها بيوصل لكل عمود إطار كعزم مركز $M = (w_s L_c^2/2)\\,S$ عند منسوب B. وبعد 2.0 م بيبقى **إطار كابولي** — كمرة كابولي متدرّجة مصبوبة مع كل عمود — والكمرة B مابقاش عليها لي. وفي الحالتين التوازن الواحد $M_F = M_{fe}\\,DF_c$ مابقاش ينفع: الإطار بيتحل بالجدول الكامل (الكابولي عضو من غير جساءة شايل عزمه $M_c$) أو بالشغل الافتراضي. وللإطار المتماثل فيه تقدير سريع $M_F = M_1 + M_c$، و $M_1 = M_{fe}\\,DF_c$ للإطار من غير الكابولي. ولما سقف هوردي مايل يخلص في بلاطة كابولي مصمتة، الاتنين بيتداخلوا عند الركيزة، فبيتسلحوا **لكل عصب** — الحديد العلوي لكل عصب بيعدّي فوق الركيزة ويكمّل في الكابولي المصمت — والجزء المصمت بياخد Ø10 زيادة بين الأعصاب."}},{t:"eq",tex:["M = \\dfrac{w_s\\,L_c^2}{2}\\,S\\quad (L_c \\le 2.0\\ \\text{m}),\\qquad M_F \\approx M_1 + M_c,\\quad M_1 = M_{fe}\\,DF_c"],caption:{en:"First: the twist of the edge beam as a moment on each column (a cantilever slab). Second: the quick estimate of the knee for a symmetric frame with cantilevers at the knees.",ar:"الأول: لي الكمرة الطرفية كعزم على كل عمود (بلاطة كابولي). التاني: التقدير السريع للركن في إطار متماثل بكوابيل عند الأركان."}},{t:"p",text:{en:"**Example.** A slab cantilever of 1.8 m, $w_s = 10$ kN/m², frames 6 m apart: $M = 10\\times1.8^2/2\\times6 = 97.2$ kN·m on each column. A 3.0 m cantilever frame carrying 60 kN/m and a 30 kN wall at its tip: $M_c = 60\\times3^2/2 + 30\\times3 = 360$ kN·m. On a two-hinged frame with $M_{fe} = 1200$ kN·m and $DF_c = 0.6$: $M_1 = 720$, and the estimate gives $M_F = 1080$ kN·m. The exact balance shares $M_c$ by the distribution factors — 864 kN·m at the beam end, 504 kN·m at the column top: the estimate is safe at the knee, overstating it by $DF_c\\,M_c = 216$ kN·m, while the mid-span moment comes out the same 216 kN·m too small.",ar:"**مثال.** بلاطة كابولي 1.8 م، و $w_s = 10$ kN/m²، والإطارات كل 6 م: $M = 10\\times1.8^2/2\\times6 = 97.2$ kN·m على كل عمود. وإطار كابولي 3.0 م شايل 60 kN/m وحائط 30 kN عند طرفه: $M_c = 60\\times3^2/2 + 30\\times3 = 360$ kN·m. وعلى إطار ذو مفصلين فيه $M_{fe} = 1200$ kN·m و $DF_c = 0.6$: $M_1 = 720$، والتقدير بيدّي $M_F = 1080$ kN·m. والتوازن المضبوط بيوزّع $M_c$ بمعاملات التوزيع — 864 kN·m عند طرف الكمرة، و 504 kN·m عند راس العمود: التقدير في الأمان عند الركن، وبيزوّده بـ $DF_c\\,M_c = 216$ kN·m، بينما عزم نص البحر بيطلع أقل بنفس الـ 216 kN·m."}},{t:"quiz",q:{kind:"num",q:{en:"An edge joint: beam K = 3, column K = 1 (relative). Distribution factor of the beam?",ar:"عقدة طرفية: K للكمرة = 3، و K للعمود = 1 (نسبي). معامل توزيع الكمرة؟"},answer:.75,tol:.003,explain:{en:"$3/(3 + 1) = 0.75$; the column takes 0.25.",ar:"$3/(3 + 1) = 0.75$؛ والعمود بياخد 0.25."}}}]},{id:"sections",title:{en:"Designing the sections for M and N",ar:"تصميم القطاعات على M و N"},blocks:[{t:"eq",tex:["\\dfrac{P}{f_{cu}\\,b\\,t} < 0.04:\\quad d = C_1\\sqrt{\\dfrac{M}{f_{cu}\\,b}},\\qquad A_s = \\dfrac{M}{J\\,f_y\\,d}","e = \\dfrac{M}{P},\\quad \\dfrac{e}{t} > 0.5:\\quad e_s = e + \\dfrac{t}{2} - c,\\quad M_s = P\\,e_s,\\quad A_s = \\dfrac{M_s}{J\\,f_y\\,d} - \\dfrac{P}{f_y/\\gamma_s}","\\mu_{min} = \\dfrac{0.225\\sqrt{f_{cu}}}{f_y},\\qquad n = \\dfrac{b - 25}{\\Phi + 25}","e = \\dfrac{M}{T},\\quad \\dfrac{e}{t} > 0.5:\\quad e_s = e - \\dfrac{t}{2} + c,\\quad M_s = T\\,e_s,\\quad A_s = \\dfrac{M_s}{J\\,f_y\\,d} + \\dfrac{T}{f_y/\\gamma_s}"],caption:{en:"First line: a small normal force is neglected — a beam. Second line: a large eccentricity — the force moved to the tension steel. Otherwise (e/t ≤ 0.5) the interaction diagrams. Third line: minimum steel ratio (with the absolute lower limits of the code), bars per layer. Fourth line: a tension T with the moment — the force moves to the tension steel from the other side, and its own steel is added.",ar:"السطر الأول: القوة العمودية الصغيرة بتتهمل — كمرة. السطر التاني: لامركزية كبيرة — القوة بتتنقل لحديد الشد. وغير كده (e/t ≤ 0.5) منحنيات التفاعل. السطر التالت: نسبة الحديد الأدنى (مع الحدود الدنيا المطلقة في الكود)، وعدد الأسياخ في الصف. السطر الرابع: شد T مع العزم — القوة بتتنقل لحديد الشد من الناحية التانية، وحديدها بيتزوّد."}},{t:"p",text:{en:"**Example** ($f_{cu} = 25$, $f_y = 400$ N/mm²). The knee of a 16 m two-hinged frame, 350 × 1300: $M = 820$ kN·m with 160 kN in the beam and 540 kN in the column. **Beam**: $160\\times10^3/(25\\times350\\times1300) = 0.014 < 0.04$ → P neglected; $d = 1200$ mm, $C_1 = 1200/\\sqrt{820\\times10^6/(25\\times350)} = 3.92$ → $J = 0.801$, $A_s = 2133$ mm² ($A_{s,min} = 0.225\\times5/400\\times350\\times1200 = 1181$) → 6Ø22 in one layer, since $n = (350 - 25)/(22 + 25) = 6.9$. **Column top**: $540\\times10^3/(25\\times350\\times1300) = 0.047 > 0.04$, $e = 820/540 = 1.519$ m, $e/t = 1.17 > 0.5$ → $e_s = 1.519 + 0.65 - 0.10 = 2.069$ m, $M_s = 1117$ kN·m, $C_1 = 3.36$ → $J = 0.772$, $A_s = 1460$ mm² → 4Ø22.",ar:"**مثال** ($f_{cu} = 25$، و $f_y = 400$ N/mm²). ركن إطار ذو مفصلين 16 م، مقاس 350 × 1300: $M = 820$ kN·m مع 160 kN في الكمرة و 540 kN في العمود. **الكمرة**: $160\\times10^3/(25\\times350\\times1300) = 0.014 < 0.04$ ← نهمل P؛ و $d = 1200$ مم، و $C_1 = 1200/\\sqrt{820\\times10^6/(25\\times350)} = 3.92$ ← $J = 0.801$، و $A_s = 2133$ مم² ($A_{s,min} = 0.225\\times5/400\\times350\\times1200 = 1181$) ← 6Ø22 في صف واحد، لأن $n = (350 - 25)/(22 + 25) = 6.9$. **راس العمود**: $540\\times10^3/(25\\times350\\times1300) = 0.047 > 0.04$، و $e = 820/540 = 1.519$ م، و $e/t = 1.17 > 0.5$ ← $e_s = 1.519 + 0.65 - 0.10 = 2.069$ م، و $M_s = 1117$ kN·m، و $C_1 = 3.36$ ← $J = 0.772$، و $A_s = 1460$ مم² ← 4Ø22."}},{t:"p",text:{en:"**Which sections.** A two-hinged frame is designed at three sections: ① the beam at the knee and ② the column top, both rectangles, and ③ mid-span, a T-section with the slab. A fixed frame adds ④ the column base, a rectangle under $M_F/2$ and the column load. A three-hinged frame needs only ① and ② — ① usually needs more steel than ②, and the difference goes in as extra top bars of the beam. Mid-span is a **rectangle** too where the slab is hollow-block (it has no solid flange) or where a sky-light opening leaves the beam bare. The flange of the frame beam, held at both knees, uses $K = 0.7$; an edge frame with its slab on one side is an L-section — of 20 m, $b = 400$, $t_s = 120$ mm, frames 6 m apart: $B_L = \\min(3000,\\ 6\\times120 + 400,\\ 0.7\\times20\\,000/10 + 400) = 1120$ mm.",ar:"**أنهي قطاعات.** الإطار ذو المفصلين بيتصمم عند تلات قطاعات: ① الكمرة عند الركن و ② راس العمود، والاتنين مستطيل، و ③ نص البحر، قطاع T مع البلاطة. والإطار الثابت بيزوّد ④ قاعدة العمود، مستطيل تحت $M_F/2$ وحمل العمود. والإطار ثلاثي المفصلات محتاج ① و ② بس — و ① غالباً محتاج حديد أكتر من ②، والفرق بيتحط حديد علوي زيادة في الكمرة. ونص البحر بيبقى **مستطيل** برضه لو البلاطة هوردي (مفيهاش شفة مصمتة) أو لو فتحة شخشيخة سايبة الكمرة من غير بلاطة. وشفة كمرة الإطار، المثبتة عند الركنين، بتاخد $K = 0.7$؛ والإطار الطرفي اللي بلاطته من ناحية واحدة قطاعه L — لبحر 20 م، و $b = 400$، و $t_s = 120$ مم، والإطارات كل 6 م: $B_L = \\min(3000,\\ 6\\times120 + 400,\\ 0.7\\times20\\,000/10 + 400) = 1120$ مم."}},{t:"eq",tex:["B_T = \\min\\left(S,\\ 16t_s + b,\\ \\dfrac{0.7\\,L}{5} + b\\right),\\qquad B_L = \\min\\left(\\dfrac{S}{2},\\ 6t_s + b,\\ \\dfrac{0.7\\,L}{10} + b\\right)","A_{s,req} < \\mu_{min}\\,b\\,d:\\quad A_s = \\min\\left(\\mu_{min}\\,b\\,d,\\ 1.3\\,A_{s,req}\\right) \\ge 0.15\\%\\,b\\,d\\ \\ (f_{cu} < 30),\\quad 0.18\\%\\,b\\,d\\ \\ (f_{cu} \\ge 30)","C_1 < C_{1,min}:\\quad d_{min} = C_{1,min}\\sqrt{\\dfrac{M_s}{f_{cu}\\,b}},\\qquad C_{1,min} = 2.78\\ (f_y = 360),\\quad 2.83\\ (f_y = 400)"],caption:{en:"First line: flange width of an inner (T) and an edge (L) frame beam. Second line: the minimum steel, for 360/520 and 400/600 steel alike — the same rule as in beams, its floor 0.15 % of b d below f_cu = 30 and 0.18 % from f_cu = 30. Third line: an over-reinforced section (C₁ < C₁,min) is preferably made deeper, with C₁ = C₁,min; the other way out is the interaction diagram with steel on both faces, read on the chart of ζ = (t − 100)/t — usually heavy and expensive.",ar:"السطر الأول: عرض الشفة لكمرة إطار داخلي (T) وإطار طرفي (L). السطر التاني: الحديد الأدنى، لحديد 360/520 و 400/600 زي بعض — نفس قاعدة الكمرات، وحدّها الأدنى 0.15% من b d تحت f_cu = 30 و 0.18% من f_cu = 30 وطالع. السطر التالت: القطاع الزائد التسليح (C₁ < C₁,min) الأفضل نعمّقه، بـ C₁ = C₁,min؛ والحل التاني منحنى التفاعل بحديد على الوشين، على منحنى ζ = (t − 100)/t — وغالباً تقيل ومكلّف."}},{t:"p",text:{en:"**Minimum steel, worked** ($f_{cu} = 25$). 400 × 1400 ($d = 1300$ mm) needing only $A_{s,req} = 1100$ mm²: $\\mu_{min}bd = 0.225\\times5/400\\times400\\times1300 = 1462.5$ and $1.3\\times1100 = 1430$ → 1430 mm², above $0.15\\%\\,bd = 780$. **Deeper, worked** ($f_y = 400$): a 400 × 1200 column top with $M = 1500$ kN·m and $P = 600$ kN: $e = 2.50$ m, $e_s = 2.50 + 0.60 - 0.10 = 3.00$ m, $M_s = 1800$ kN·m and $\\sqrt{M_s/(f_{cu}b)} = 424.3$ mm, so $C_1 = 1100/424.3 = 2.59 < 2.83$. $d_{min} = 2.83\\times424.3 = 1201$ mm → $d = 1250$, $t = 1350$ mm, and the section is designed again with the new $t$: $e_s = 3.075$ m, $M_s = 1845$ kN·m, $C_1 = 2.91$ — under-reinforced now, $J = 0.733$, $A_s = 1845\\times10^6/(0.7333\\times400\\times1250) - 600\\times10^3/347.8 = 3307$ mm².",ar:"**الحديد الأدنى بالأرقام** ($f_{cu} = 25$). قطاع 400 × 1400 ($d = 1300$ مم) محتاج $A_{s,req} = 1100$ مم² بس: $\\mu_{min}bd = 0.225\\times5/400\\times400\\times1300 = 1462.5$ و $1.3\\times1100 = 1430$ ← 1430 مم²، وده أكبر من $0.15\\%\\,bd = 780$. **التعميق بالأرقام** ($f_y = 400$): راس عمود 400 × 1200 عليه $M = 1500$ kN·m و $P = 600$ kN: $e = 2.50$ م، و $e_s = 2.50 + 0.60 - 0.10 = 3.00$ م، و $M_s = 1800$ kN·m، و $\\sqrt{M_s/(f_{cu}b)} = 424.3$ مم، يعني $C_1 = 1100/424.3 = 2.59 < 2.83$. و $d_{min} = 2.83\\times424.3 = 1201$ مم ← $d = 1250$، و $t = 1350$ مم، والقطاع بيتصمم تاني بالـ $t$ الجديد: $e_s = 3.075$ م، و $M_s = 1845$ kN·m، و $C_1 = 2.91$ — بقى ناقص التسليح، و $J = 0.733$، و $A_s = 1845\\times10^6/(0.7333\\times400\\times1250) - 600\\times10^3/347.8 = 3307$ مم²."}},{t:"p",text:{en:"**Tension with bending, worked.** A frame beam pulled by a tie, or the arm of a cantilever frame pulled by the roof it carries, is designed for $M$ and a tension $T$ ($f_y = 400$): a 400 × 700 member with $M = 300$ kN·m and $T = 80$ kN: $e = 3.75$ m, $e/t = 5.4 > 0.5$ → $e_s = 3.75 - 0.35 + 0.05 = 3.45$ m, $M_s = 80\\times3.45 = 276$ kN·m, $C_1 = 3.91$ → $J = 0.800$, $A_s = 276\\times10^6/(0.800\\times400\\times650) + 80\\times10^3/347.8 = 1326 + 230 = 1556$ mm² → 5Ø20, and $0.4\\times1556 = 622$ mm² → 2Ø20 on the compression face.",ar:"**الشد مع الانحناء بالأرقام.** كمرة إطار بيشدها شداد، أو دراع إطار كابولي بيشده السقف اللي شايله، بتتصمم على $M$ وشد $T$ ($f_y = 400$): عضو 400 × 700 عليه $M = 300$ kN·m و $T = 80$ kN: $e = 3.75$ م، و $e/t = 5.4 > 0.5$ ← $e_s = 3.75 - 0.35 + 0.05 = 3.45$ م، و $M_s = 80\\times3.45 = 276$ kN·m، و $C_1 = 3.91$ ← $J = 0.800$، و $A_s = 276\\times10^6/(0.800\\times400\\times650) + 80\\times10^3/347.8 = 1326 + 230 = 1556$ مم² ← 5Ø20، و $0.4\\times1556 = 622$ مم² ← 2Ø20 على وش الضغط."}},{t:"lab",lab:"rcframe",height:470,props:{mode:"studio",lockMode:!0,preset:"portal",params:r,defaultTab:"design",missions:o},caption:{en:"A 16 m two-hinged portal in the RC frame studio: click the critical sections and read how each one is designed.",ar:"إطار بوابي ذو مفصلين 16 م في استوديو الإطارات الخرسانية: اضغط على القطاعات الحرجة واقرا كل واحد بيتصمم إزاي."}},{t:"quiz",q:{kind:"num",q:{en:"M = 500 kN·m, P = 250 kN, t = 1.0 m, c = 0.05 m. Eccentricity from the tension steel e_s (m)?",ar:"M = 500 kN·m، و P = 250 kN، و t = 1.0 م، و c = 0.05 م. اللامركزية من حديد الشد e_s (م)؟"},answer:2.45,tol:.003,unit:"m",explain:{en:"$e = 2.0$ m, $e/t = 2 > 0.5$: $e_s = 2.0 + 0.5 - 0.05 = 2.45$ m.",ar:"$e = 2.0$ م، و $e/t = 2 > 0.5$: $e_s = 2.0 + 0.5 - 0.05 = 2.45$ م."}}}]},{id:"knees",title:{en:"Knees, columns, buckling and the bar layout",ar:"الأركان والأعمدة والانبعاج وتوزيع الحديد"},blocks:[{t:"steps",items:[{en:"Under gravity the knee **closes** (tension on the outside): the outer bars run round the corner, extra bent bars stiffen it and closed stirrups hold the diagonal compression.",ar:"تحت الأحمال الرأسية الركن **بيقفل** (الشد بره): الحديد الخارجي بيلف حوالين الركن، وأسياخ مكسحة زيادة بتقويه، وكانات مقفلة بتمسك الضغط المايل."},{en:"**Stirrup hangers** on the compression face of every critical section: $0.4\\,A_s$ of the tension steel, and side bars in members deeper than 700 mm.",ar:"**كانات تعليق** على وش الضغط في كل قطاع حرج: $0.4\\,A_s$ من حديد الشد، وأسياخ جانبية في العناصر الأعمق من 700 مم."},{en:"Every section keeps the minimum steel — $\\mu_{min}\\,b\\,d$, or $1.3\\,A_{s,req}$ where that is smaller, never below $0.15\\%\\,b\\,d$ ($0.18\\%\\,b\\,d$ when $f_{cu} \\ge 30$); bars are counted per layer with $n = (b - 25)/(\\Phi + 25)$.",ar:"كل قطاع بياخد الحديد الأدنى — $\\mu_{min}\\,b\\,d$، أو $1.3\\,A_{s,req}$ لو أصغر، ومش أقل من $0.15\\%\\,b\\,d$ أبداً ($0.18\\%\\,b\\,d$ لو $f_{cu} \\ge 30$)؛ والأسياخ بتتعد في الصف بـ $n = (b - 25)/(\\Phi + 25)$."},{en:"The columns carry an external moment and the frame sways: check buckling. A column with a rigid knee and a hinge at its foot has $k = 1.6$; a fixed one $k = 1.2$ (unbraced frames).",ar:"الأعمدة شايلة عزم خارجي والإطار بيتحرك جنب: راجع الانبعاج. العمود اللي ركنه جاسئ ورجله مفصلة $k = 1.6$؛ والثابت $k = 1.2$ (إطارات غير مقيدة)."}]},{t:"eq",tex:["\\lambda = \\dfrac{k\\,H}{t} > 10:\\qquad \\delta = \\dfrac{\\lambda^2\\,t}{2000},\\qquad M_{add} = P\\,\\delta"],caption:{en:"The design moment at the column head becomes M + M_add.",ar:"عزم التصميم عند راس العمود بيبقى M + M_add."}},{t:"p",text:{en:"**Example.** The 16 m frame's column, 7 m high and 1.30 m deep at the knee, tapered to its hinge: with its $\\tfrac56 t$ prism, $t = 1.083$ m, $\\lambda = 1.6\\times7/1.083 = 10.34 > 10$ → $\\delta = 10.34^2\\times1.083/2000 = 0.058$ m and $M_{add} = 540\\times0.058 = 31.3$ kN·m on top of the 820. The same column fixed at its foot and prismatic: $\\lambda = 1.2\\times7/1.3 = 6.5$ — short.",ar:"**مثال.** عمود إطار الـ 16 م، ارتفاعه 7 م وعمقه 1.30 م عند الركن ومتدرّج لحد مفصلته: بمنشور الـ $\\tfrac56 t$، $t = 1.083$ م، و $\\lambda = 1.6\\times7/1.083 = 10.34 > 10$ ← $\\delta = 10.34^2\\times1.083/2000 = 0.058$ م و $M_{add} = 540\\times0.058 = 31.3$ kN·m فوق الـ 820. ونفس العمود لو ثابت عند رجله ومنشوري: $\\lambda = 1.2\\times7/1.3 = 6.5$ — قصير."}},{t:"p",text:{en:"In most hall frames the check comes out short, and the buckling effect is then neglected in the design of the column sections: a two-hinged column 6.5 m high and 1.30 m deep at the knee has $\\lambda = 1.6\\times6.5/1.083 = 9.6$, a fixed one 6.0 m high and 1.30 m deep $\\lambda = 1.2\\times6.0/1.3 = 5.5$ — both below 10.",ar:"في أغلب إطارات الصالات المراجعة بتطلع العمود قصير، وساعتها تأثير الانبعاج بيتهمل في تصميم قطاعات الأعمدة: عمود ذو مفصلين ارتفاعه 6.5 م وعمقه 1.30 م عند الركن $\\lambda = 1.6\\times6.5/1.083 = 9.6$، وعمود ثابت ارتفاعه 6.0 م وعمقه 1.30 م $\\lambda = 1.2\\times6.0/1.3 = 5.5$ — الاتنين أقل من 10."}},{t:"table",head:[{en:"Bars",ar:"الحديد"},{en:"three-hinged",ar:"ثلاثي المفصلات"},{en:"two-hinged and fixed",ar:"ذو مفصلين وثابت"},{en:"gable",ar:"جمالوني"}],rows:[[{en:"knee top bars into the beam",ar:"حديد الركن العلوي داخل الكمرة"},{en:"to $L/3$",ar:"لحد $L/3$"},{en:"two groups, to $L/5$ and $L/4$",ar:"مجموعتين، لحد $L/5$ و $L/4$"},{en:"$L'/5$ and $L'/4$ along the slope",ar:"$L'/5$ و $L'/4$ على الميل"}],[{en:"span bottom bars",ar:"حديد البحر السفلي"},"—",{en:"half into the knees, half stopped $0.15L$ short",ar:"النص داخل الأركان، والنص بيقف قبلها بـ $0.15L$"},{en:"half stopped $0.15L'$ short",ar:"النص بيقف قبلها بـ $0.15L'$"}],[{en:"extra column bars",ar:"حديد العمود الإضافي"},{en:"$H/3$ up from the hinge",ar:"$H/3$ فوق المفصلة"},{en:"two-hinged: $H/3$ up from the hinge; fixed: inner dowels $2H/3$ up from the footing, outer bars down to $H/3$ above it",ar:"ذو مفصلين: $H/3$ فوق المفصلة؛ ثابت: الأشاير الداخلية $2H/3$ فوق القاعدة، والحديد الخارجي نازل لحد $H/3$ فوقها"},{en:"as the straight frames",ar:"زي الإطارات المستقيمة"}],[{en:"stirrups concentrated",ar:"تركيز الكانات"},{en:"at the crown and at the base hinges",ar:"عند التاج وعند مفصلات القواعد"},{en:"at the base hinges (two-hinged)",ar:"عند مفصلات القواعد (ذو مفصلين)"},{en:"at the base hinges, and crossed at the ridge",ar:"عند مفصلات القواعد، ومتقاطعة عند خط القمة"}]],caption:{en:"L′ = the whole sloping length of a gable. Concentrated stirrups: 10Ø10 per metre over 1.0 m (or t) at every real hinge.",ar:"L′ = الطول المايل كله للجمالوني. تركيز الكانات: 10Ø10 في المتر على طول 1.0 م (أو t) عند كل مفصلة حقيقية."}},{t:"steps",items:[{en:"**Outer bars**: the column steel $A_{s2}$ runs round the knee into the beam top in two halves; the beam adds $A_{s1} - A_{s2}$ as extra top bars, and a **U-bar** closes the outer corner.",ar:"**الحديد الخارجي**: حديد العمود $A_{s2}$ بيلف حوالين الركن ويدخل فوق في الكمرة على نصين؛ والكمرة بتزوّد $A_{s1} - A_{s2}$ حديد علوي إضافي، وسيخ على شكل **U** بيقفل الركن من بره."},{en:"**Hangers**: $0.4\\,A_s$ of the opposite steel on every compression face — the beam bottom at the knee ($0.4\\,A_{s1}$), its top at mid-span ($0.4\\,A_{s3}$) and the inner face of the column ($0.4\\,A_{s2}$); at a fixed base the L-bars $A_{s4}$ on the inner face.",ar:"**حديد التعليق**: $0.4\\,A_s$ من الحديد المقابل على كل وش ضغط — تحت في الكمرة عند الركن ($0.4\\,A_{s1}$)، وفوق في نص البحر ($0.4\\,A_{s3}$)، والوش الداخلي للعمود ($0.4\\,A_{s2}$)؛ وعند الركيزة الثابتة أسياخ الـ L $A_{s4}$ على الوش الداخلي."},{en:"**Stirrups**: the columns 5Ø8 per metre; in the knee block the stirrups of beam and column overlap into a mesh; the beam stirrups follow the shear at the knee, with 5Ø8 per metre in the middle zone.",ar:"**الكانات**: الأعمدة 5Ø8 في المتر؛ وفي بلوك الركن كانات الكمرة والعمود بتتداخل وتعمل شبكة؛ وكانات الكمرة ماشية مع القص عند الركن، و 5Ø8 في المتر في المنطقة الوسطانية."},{en:"**Side bars**: 2Ø10 every 300 mm on the beam faces, 2Ø12 every 250 mm on the long faces of the columns, held by overlapping closed ties.",ar:"**الأسياخ الجانبية**: 2Ø10 كل 300 مم على وشوش الكمرة، و 2Ø12 كل 250 مم على الوشوش الطويلة للأعمدة، ماسكاها كانات مقفلة متداخلة."},{en:"**Ridge and inner corners**: the inner bars of each rafter run straight on past the ridge, cross, and anchor in the top zone of the other rafter (the same at the inner corner of a knee); the outer bars bend over the convex top.",ar:"**خط القمة والأركان الداخلية**: الحديد الداخلي لكل كمرة مائلة بيكمّل مستقيم بعد خط القمة، ويتقاطع، ويتثبت في المنطقة العلوية للكمرة التانية (ونفس الكلام عند الركن الداخلي)؛ والحديد الخارجي بيتكسّح فوق القمة المحدّبة."},{en:"**A hall frame under a saw-tooth roof** is detailed the same way: the outer bars close as **loops** round the knee, with some bent diagonally across it; a 1.5 m beam gets **skin bars** 4 × 2Ø10 on its faces; the column narrows to its **hinge throat** with closely spaced stirrups over the last 1.0 m; every **corbel** that carries a floating bay gets a **loop** bar of its own with closed ties; and the bars of a middle column run up into the beam and are bent into it both ways.",ar:"**إطار الصالة تحت سقف منشاري** بيتسلّح بنفس الطريقة: الحديد الخارجي بيتقفل **عروات (Loop)** حوالين الركن، وجزء منه متكسّح بالميل عبر الركن؛ وكمرة عمقها 1.5 م بتاخد **أسياخ جانبية** 4 × 2Ø10 على وشوشها؛ والعمود بيضيق لحد **رقبة المفصلة** بكانات متقاربة على آخر 1.0 م؛ وكل **كابولي قصير** شايل باكية عائمة بياخد سيخ **عروة (Loop)** خاص بيه بكانات مقفلة؛ وحديد العمود الوسطاني بيطلع في الكمرة ويتكسّح فيها في الاتجاهين."}]},{t:"p",text:{en:"**Example** — a 20 m two-hinged frame on 7.5 m columns: the knee top bars stop 4.0 m and 5.0 m into the span; half the bottom bars stop 3.0 m short of each knee; the extra column bars run 2.5 m up from the hinge. Fixed instead: inner dowels 5.0 m up from the footing, the outer knee bars down to 2.5 m above it, lapping the outer dowels. As a gable with a 2 m rise ($L' = 20.40$ m): 4.08, 5.10 and 3.06 m along the slope.",ar:"**مثال** — إطار ذو مفصلين 20 م على أعمدة 7.5 م: الحديد العلوي للركن بيقف على 4.0 م و 5.0 م جوه البحر؛ ونص الحديد السفلي بيقف قبل كل ركن بـ 3.0 م؛ والحديد الإضافي للعمود بيطلع 2.5 م فوق المفصلة. ولو ثابت: الأشاير الداخلية 5.0 م فوق القاعدة، والحديد الخارجي للركن نازل لحد 2.5 م فوقها، بوصلة تراكب مع الأشاير الخارجية. ولو جمالوني بارتفاع 2 م ($L' = 20.40$ م): 4.08 و 5.10 و 3.06 م على الميل."}},{t:"quiz",q:{kind:"tf",q:{en:"The tapered column of a two-hinged frame never needs the additional moment of buckling.",ar:"العمود المتدرّج في الإطار ذو المفصلين عمره ما بيحتاج العزم الإضافي للانبعاج."},answer:!1,explain:{en:"Hinged at its foot in a frame that sways, it has k = 1.6: a 7 m column 1.3 m deep is already slender (λ = 10.3).",ar:"مفصلي عند رجله في إطار بيتحرك جنب، فـ k = 1.6: عمود 7 م وعمقه 1.3 م نحيف فعلاً (λ = 10.3)."}}}]},{id:"apply",title:{en:"Your building: the sections of the workshop frame",ar:"مبناك: قطاعات إطار الورشة"},blocks:[{t:"p",text:{en:"The RC workshop spans 12 m on medium soil: the soil rule gives the **two-hinged frame** (12–22 m), with a 300 × 1000 beam — $L/12$, the deep end of $L/12$–$L/14$ (1.00–0.86 m); a three-hinged frame would need $L/10 = 1.20$ m, a fixed one only 0.86–0.75 m. Its load: the five secondary beams inside the span smeared, $w = 9.24 + 5\\times139.95/12 = 67.55$ kN/m, while the two over the knees, 79.95 kN each, go straight into the columns. Its analysis: $M_F = 810.6\\times0.368 = 298.7$ kN·m, $X = 49.8$ kN, $Y = 67.55\\times6 + 79.95 = 485.3$ kN, $1215.9 - 298.7 = 917.3$ kN·m at mid-span. The three critical sections ($f_{cu} = 25$, $f_y = 400$):",ar:"الورشة الخرسانية بحرها 12 م على تربة متوسطة: قاعدة التربة بتدّي **الإطار ذو المفصلين** (12–22 م)، بكمرة 300 × 1000 — $L/12$، الطرف العميق من $L/12$–$L/14$ (1.00–0.86 م)؛ والإطار ثلاثي المفصلات كان هيحتاج $L/10 = 1.20$ م، والثابت 0.86–0.75 م بس. وحمله: الخمس كمرات المتشالة اللي جوه البحر مفروشين، $w = 9.24 + 5\\times139.95/12 = 67.55$ kN/m، والاتنين اللي فوق الأركان، 79.95 kN لكل واحدة، بينزلوا في الأعمدة على طول. وتحليله: $M_F = 810.6\\times0.368 = 298.7$ kN·m، و $X = 49.8$ kN، و $Y = 67.55\\times6 + 79.95 = 485.3$ kN، و $1215.9 - 298.7 = 917.3$ kN·m في نص البحر. والقطاعات الحرجة التلاتة ($f_{cu} = 25$، و $f_y = 400$):"}},{t:"steps",items:[{en:"**Beam at the knee.** $N = X = 49.8$ kN: $49.8\\times10^3/(25\\times300\\times1000) = 0.007 < 0.04$ → a beam. $d = 950$ mm, $C_1 = 4.76$ → $J = 0.824$, $A_s = 954$ mm² ($A_{s,min} = 802$) → 4Ø18 at the top, and $0.4\\times954 = 381$ mm² → 2Ø16 at the bottom.",ar:"**الكمرة عند الركن.** $N = X = 49.8$ kN: $49.8\\times10^3/(25\\times300\\times1000) = 0.007 < 0.04$ ← كمرة. و $d = 950$ مم، و $C_1 = 4.76$ ← $J = 0.824$، و $A_s = 954$ مم² ($A_{s,min} = 802$) ← 4Ø18 فوق، و $0.4\\times954 = 381$ مم² ← 2Ø16 تحت."},{en:"**Mid-span.** A T-section with the roof slab in compression, the beam held at both knees ($K = 0.7$): $B = \\min(6000,\\ 16\\times120 + 300,\\ 0.7\\times12000/5 + 300) = 1980$ mm; $C_1 = 6.98$ → $J = 0.826$, $A_s = 2922$ mm², the stress block 95 mm deep inside the 120 mm slab → 8Ø22 in two layers (five and three), and $0.4\\times2922 = 1169$ mm² → 4Ø20 on top.",ar:"**نص البحر.** قطاع T وبلاطة السقف في الضغط، والكمرة مثبتة عند الركنين ($K = 0.7$): $B = \\min(6000,\\ 16\\times120 + 300,\\ 0.7\\times12000/5 + 300) = 1980$ مم؛ و $C_1 = 6.98$ ← $J = 0.826$، و $A_s = 2922$ مم²، ومستطيل الإجهادات عمقه 95 مم جوه البلاطة 120 مم ← 8Ø22 في صفين (خمسة وتلاتة)، و $0.4\\times2922 = 1169$ مم² ← 4Ø20 فوق."},{en:"**Column top.** Unbraced, $k = 1.6$; with its $\\tfrac56 t$ prism (0.667 m) $\\lambda = 14.4$ → $\\delta = 0.069$ m, $M_{add} = 485.3\\times0.069 = 33.5$ kN·m. $e = 332.2/485.3 = 0.685$ m, $e/t = 0.86 > 0.5$ → $e_s = 0.685 + 0.40 - 0.05 = 1.035$ m, $M_s = 502.1$ kN·m, $C_1 = 2.90 > 2.83$: under-reinforced, no deeper column and no compression steel needed. $J = 0.732$, $A_s = 502.1\\times10^6/(0.732\\times400\\times750) - 485.3\\times10^3/347.8 = 2286 - 1395 = 891$ mm² → 4Ø18 on the outer face, and $0.4\\times891 = 357$ mm² → 2Ø16 on the inner face.",ar:"**راس العمود.** غير مقيد، $k = 1.6$؛ وبمنشور الـ $\\tfrac56 t$ (0.667 م) $\\lambda = 14.4$ ← $\\delta = 0.069$ م، و $M_{add} = 485.3\\times0.069 = 33.5$ kN·m. و $e = 332.2/485.3 = 0.685$ م، و $e/t = 0.86 > 0.5$ ← $e_s = 0.685 + 0.40 - 0.05 = 1.035$ م، و $M_s = 502.1$ kN·m، و $C_1 = 2.90 > 2.83$: ناقص التسليح، ومش محتاج لا عمود أعمق ولا حديد ضغط. و $J = 0.732$، و $A_s = 502.1\\times10^6/(0.732\\times400\\times750) - 485.3\\times10^3/347.8 = 2286 - 1395 = 891$ مم² ← 4Ø18 على الوش الخارجي، و $0.4\\times891 = 357$ مم² ← 2Ø16 على الوش الداخلي."}]},{t:"p",text:{en:"The footing is shifted 0.095 m outwards under the thrust, as found in the indeterminate-systems episode. Click a truss of the workshop to see the frame that replaces it.",ar:"والقاعدة مترحّلة 0.095 م لبره تحت الدفع، زي ما طلع في حلقة حل الأنظمة غير المحددة. اضغط على جمالون من جمالونات الورشة تشوف الإطار اللي بيحل محله."}},{t:"widget",w:"building",props:{focus:"WT-1",tags:["ws-columns","ws-trusses","sys-indet","sys-intro","sys-frames"]}},{t:"quiz",q:{kind:"num",q:{en:"The workshop frame: additional moment of buckling at the column top (kN·m)?",ar:"إطار الورشة: العزم الإضافي للانبعاج عند راس العمود (kN·m)؟"},answer:33.54,tol:.006,unit:"kN·m",explain:{en:"$\\lambda = 1.6\\times6/0.667 = 14.4$, $\\delta = 14.4^2\\times0.667/2000 = 0.069$ m, $M_{add} = 485.3\\times0.069 = 33.5$ kN·m.",ar:"$\\lambda = 1.6\\times6/0.667 = 14.4$، و $\\delta = 14.4^2\\times0.667/2000 = 0.069$ م، و $M_{add} = 485.3\\times0.069 = 33.5$ kN·m."}}}]}],quiz:[{kind:"mcq",q:{en:"A 20 m hall on weak clay. The system?",ar:"صالة 20 م على طين ضعيف. النظام؟"},options:[{en:"a tied polygon frame",ar:"إطار مضلع بشداد"},{en:"a three-hinged frame",ar:"إطار ثلاثي المفصلات"},{en:"a fixed frame",ar:"إطار ثابت الركائز"}],answer:0,explain:{en:"Weak soil calls for a system that a settling footing cannot bend: the three-hinged frame covers 12–16 m; beyond 16 m comes the tied polygon frame on a hinge and a roller, up to 24 m.",ar:"التربة الضعيفة عايزة نظام القاعدة اللي بتهبط ماتقدرش تحنيه: الإطار ثلاثي المفصلات بيغطي 12–16 م؛ وبعد 16 م بييجي الإطار المضلع بشداد على مفصلة وركيزة متحركة، لحد 24 م."}},{kind:"num",q:{en:"A fixed frame of 20 m by the middle of its depth rule, L/15 (m)?",ar:"إطار ثابت 20 م بمنتصف قاعدة عمقه، L/15 (م)؟"},answer:1.3333,tol:.003,unit:"m",explain:{en:"$20/15 = 1.33$ m, inside $L/14 \\to L/16 = 1.43 \\to 1.25$ m.",ar:"$20/15 = 1.33$ م، جوه $L/14 \\to L/16 = 1.43 \\to 1.25$ م."}},{kind:"num",q:{en:"A straight three-hinged frame: L = 16 m, h = 6 m, w = 45 kN/m. Thrust X (kN)?",ar:"إطار ثلاثي المفصلات مستقيم: L = 16 م، و h = 6 م، و w = 45 kN/m. الدفع الأفقي X (kN)؟"},answer:240,tol:.003,unit:"kN",explain:{en:"$45\\times256/(8\\times6) = 240$ kN.",ar:"$45\\times256/(8\\times6) = 240$ kN."}},{kind:"tf",q:{en:"More redundants give a frame smaller moments but make it more sensitive to settlement.",ar:"المجاهيل الزيادة الأكتر بتدّي الإطار عزوم أصغر بس بتخليه أحسس للهبوط."},answer:!0,explain:{en:"The fixed frame has the smallest moments and is the one a settling footing bends most.",ar:"الإطار الثابت عزومه الأصغر، وهو اللي القاعدة اللي بتهبط بتحنيه أكتر حاجة."}},{kind:"num",q:{en:"Hinged base: X = 150 kN, t₁ + t₂ = 1.0 m, Y = 600 kN. Footing shift (m)?",ar:"ركيزة مفصلية: X = 150 kN، و t₁ + t₂ = 1.0 م، و Y = 600 kN. ترحيل القاعدة (م)؟"},answer:.25,tol:.003,unit:"m",explain:{en:"$150\\times1.0/600 = 0.25$ m outwards.",ar:"$150\\times1.0/600 = 0.25$ م لبره."}},{kind:"num",q:{en:"A 400 mm wide section with Ø20 bars. Bars per layer?",ar:"قطاع عرضه 400 مم بأسياخ Ø20. عدد الأسياخ في الصف؟"},answer:8,tol:.001,explain:{en:"$(400 - 25)/(20 + 25) = 8.3$ → 8 bars.",ar:"$(400 - 25)/(20 + 25) = 8.3$ ← 8 أسياخ."}},{kind:"mcq",q:{en:"A frame section may be designed as a beam, neglecting P, when…",ar:"قطاع الإطار ينفع يتصمم ككمرة ونهمل P لما…"},options:[{en:"P/(f_cu·b·t) < 0.04",ar:"P/(f_cu·b·t) < 0.04"},{en:"e/t < 0.5",ar:"e/t < 0.5"},{en:"the section is in a column",ar:"القطاع في عمود"}],answer:0,explain:{en:"A normal force below 4% of f_cu·b·t hardly changes the steel; e/t decides only between the e_s method and the charts.",ar:"قوة عمودية أقل من 4% من f_cu·b·t تقريباً مابتغيّرش الحديد؛ و e/t بتفرق بس بين طريقة e_s والمنحنيات."}},{kind:"num",q:{en:"M = 600 kN·m, P = 400 kN, t = 1.0 m, c = 0.05 m. M_s (kN·m)?",ar:"M = 600 kN·m، و P = 400 kN، و t = 1.0 م، و c = 0.05 م. M_s (kN·m)؟"},answer:780,tol:.003,unit:"kN·m",explain:{en:"$e = 1.5$ m, $e_s = 1.5 + 0.5 - 0.05 = 1.95$ m, $M_s = 400\\times1.95 = 780$ kN·m.",ar:"$e = 1.5$ م، و $e_s = 1.5 + 0.5 - 0.05 = 1.95$ م، و $M_s = 400\\times1.95 = 780$ kN·m."}}]};export{m as default};
